// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_9: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.portrait-of-spite","name":"Portrait of Spite","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["curse"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"7 days"},"cost":"splendid art supplies worth at least 100 gp × the target's level, at least one pint of blood from the target"},"targeting":{"range":{"kind":"NONE"},"target":"1 living creature","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion (master)","secondaryChecks":"Crafting, Occultism or Religion (whichever isn't used for the primary check)","secondaryCasters":3},"description":"Using the blood, you compose a portrait of the target in perfect health. Once the portrait is complete, you recite your grievances against the target and enact on the portrait the punishments you wish to see them face, choosing from the clumsy, enfeebled, drained, or stupefied condition.\n\nThe target must attempt a Will saving throw. You're only able to perform this ritual if you know the target's name and are able to see their face clearly in your mind's eye, and the secondary caster who performs the Crafting check must be able to paint or draw the target from memory. The target suffers the effects over the course of 1d6 hours, during which time the portrait transforms to reveal a caricature of the punishment you chose-muscles atrophied into nothing for enfeebled, pallid and sickly for drained, and so on. The target is immediately aware that they're under the effects of a magical ailment. If the duration expires or the target removes the curse with a remove curse or similar effect, their portrait slowly returns back to its original form. Destroying the portrait also ends the effect immediately.\n\nCritical Success The target is either Clumsy 4, Drained 4, Enfeebled 4, or Stupefied 4, depending on the punishment you chose. On a successful Will save, the condition value is 2, and the target is unaffected on a critical success.\n\nSuccess The target is either Clumsy 2, Drained 2, Enfeebled 2, or Stupefied 2, depending on the punishment you chose. On a successful Will save, the condition value is 1, and the target is unaffected on a critical success.\n\nFailure The portrait doesn't change, and the ritual has no effect on the target.\n\nCritical Failure The portrait turns into a sickening mimicry of your form and the forms of the secondary casters, and the blood of your target extracts itself from the canvas, dripping down and drying immediately to prevent you from reattempting the ritual. Over the course of the next 1d6 hours, you and the secondary casters experience the curse you had intended to place upon the target with the effects of a critical success.","source":{"provider":"PAIZO","sourceId":"Z60JRD78wT3afOEJ","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.portrait-of-the-artist","name":"Portrait of the Artist","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You change your appearance to look like a well-known artist talented at a particular craft or performance, such as a painter, singer, or orator, with the effects of illusory disguise. Additionally, you appear to mimic their skill, although such appearances are merely an illusion. If they are famous for physical art, the spell creates illusions of physical artwork matching their style, and onlookers who don't disbelieve are convinced these works are as impressive as the real thing. If they are famous for their ability to perform, you create an illusory performance that tricks onlookers into thinking you are as skillful as the performer you're pretending to be. The audience can disbelieve this spell if they interact with your art or actively listen to the performance, using either Perception or an appropriate Lore, whichever is higher. When the duration ends, any fake art disappears, and those who were duped by a performance realize it wasn't as good as they thought, though they still might not discover that you weren't really the artist you claimed to be.\n\nThis spell can't grant you any benefits from special abilities that take such skill they require a Performance check, such as the lingering performance focus spell. Using the spell to maintain the ruse long enough to Earn Income from your art is also quite difficult; because it requires careful timing and repeated deceit, it can't be assumed to automatically work on an Earn Income check.","source":{"provider":"PAIZO","sourceId":"CuRat8IXBUu9C3Yw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pressure-zone","name":"Pressure Zone","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Air pressure drops precipitously, causing pain and debilitation in creatures' inner ears and joints. Each living creature in the area of the spell when you cast it or that enters the area during the spell's duration must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is and Clumsy 1 until the end of its next turn, after which it's temporarily immune for 1 hour.\n\nFailure The creature is deafened and Clumsy 2. At the end of each of its turns, it can attempt a new save if it's no longer in the pressure zone. On a success, it ends the effects and is temporarily immune for 1 hour.\n\nCritical Failure The creature is deafened and clumsy 2 for the duration of the spell.\n\nA creature by this spell can attempt to end the condition by popping its ears. It can use a single action to attempt a new Fortitude save, losing the deafened condition from this spell on a success. Some creatures with anatomies that lack inner ears or joints might be immune to these effects, as determined by the GM.","source":{"provider":"PAIZO","sourceId":"e4c73RBCQAZdYxau","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pulverizing-wake","name":"Pulverizing Wake","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","ranger","sonic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"1 creature within reach","area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"ZJn9o8o0gXmwHkcK","formula":"6d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ZJn9o8o0gXmwHkcK":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Imitating raptorial creatures, you attack with such speed it drives a sonic shockwave. Make a melee Strike against a creature in your reach; if you hit, you deal an additional 3d8 sonic damage. Regardless of the result of your Strike, that creature becomes the point of origin of a 15-foot cone, aimed directly away from you. All creatures in that cone take 6d8 sonic damage (basic Fortitude save).\n\nHeightened (+1) The damage of the cone increases by 1d8.","source":{"provider":"PAIZO","sourceId":"EiE1A8TCeJGVzzV2","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.quicken-time","name":"Quicken Time","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You speed up the time stream in an area, stretching and pulling it until time flows swift and wild. Any creature that begins its turn in the area is until the end of its turn and can use the extra action only to Stride or Strike. Unfortunately, speeding up time is much more difficult than slowing it down, and the effect is uneven and jittery, making accuracy between times painfully difficult; creatures inside the area are to those outside it, and vice versa.","source":{"provider":"PAIZO","sourceId":"lETZeqBPoj2htGVk","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rallying-banner","name":"Rallying Banner","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["auditory","concentrate","illusion","manipulate","visual"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an illusory banner representing a revolution, social movement, or organization such as the Firebrands. This banner is 30 feet tall, 30 feet wide, and hovers 20 feet in the air above the target. The banner is surrounded by flashing colors, bursting fireworks, and the sounds of cheering crowds, which draw attention and make it clearly obvious that the target is the bearer of the banner.\n\nYour allies and any members of the banner's associated group who are within 200 feet and who can see and hear the banner are inspired by its presence. They gain a +1 status bonus to attack rolls and a +1 status bonus to saves against fear, emotion effects that inflict despair, and effects that would impose the or condition. When the bearer of the banner would gain the condition, they can choose to stand their ground and be for the effect's duration instead. During the duration, the target can touch a willing creature and transfer the banner to the touched creature, making them the new bearer of the banner. Touching a creature for this purpose is an action with the concentrate and manipulate traits.","source":{"provider":"PAIZO","sourceId":"Hp2wmnRS6TUGZlZ2","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ravening-maw","name":"Ravening Maw","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","evil","healing","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"one living creature","area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You evoke Zevgavizeb's unceasing hunger and inflict it upon your target. The target becomes overwhelmed with cannibalistic hunger and can restore its vitality by feasting on the flesh of the fallen. On its turn, the target can use 2 actions (these actions have the manipulate trait) to cannibalize an adjacent or dead creature. If the cannibalized creature is Dying, it dies. If the cannibalized creature is an ally of the target, the target regains 5d8 HP; otherwise, the target regains 5d4 HP. Certain monsters (such as those whose blood is acidic or magical) might inflict additional effects on those who cannibalize them at the GM's discretion. Once cannibalized, a particular creature's body doesn't have enough meat to cannibalize again. During any round that there's a Dying or dead creature within 30 feet of the target, if the target can't or doesn't cannibalize a creature, the target takes 5d4 mental damage.\n\nHeightened (+1) The amount of HP restored by cannibalizing a creature increases by 1d8 for eating an ally and 1d4 otherwise, and the mental damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"VDWIZuLOJqwBthHc","book":"Pathfinder #153: Life's Long Shadows","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.redistribute-potential","name":"Redistribute Potential","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","cold","concentrate","fire","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"SQUARE","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"8ansf0q0mmysn22a","formula":"4d4","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"8ansf0q0mmysn22a":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area two adjacent 5-foot squares\nEnergy attempts to balance out, but with your magic, you can shunt all the energy in one area to another. Creatures in either area take 4d4 damage with a basic Fortitude save. Choose one of the squares to steal heat, dealing cold damage, and the other to concentrate the stolen heat, dealing fire damage. A creature that fails its save also becomes Clumsy 1 from numbness if it's in the area of stolen heat or Enfeebled 1 from heat stroke if it's in the area of concentrated heat; these conditions last until the start of your next turn. If a creature is large enough to be in both squares, you choose only one of the areas for it to attempt its save against; it's unaffected by the other area.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"bZMwSGc9t5K7uxZV","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.repelling-pulse","name":"Repelling Pulse","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"7d10","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash a powerful pulse of telekinetic power, and the pulse violently hurls creatures away from you. Each creature in the area takes 7d10 force damage depending on its Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is pushed 10 feet away from you.\n\nCritical Failure The creature takes double damage. The creature is pushed 20 feet away from you and is then knocked .\n\nHeightened (+2) The force damage increases by 2d10, and the distance the target is moved on a failure and critical failure increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"TLqMFgCewxuricJw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.restorative-moment","name":"Restorative Moment","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron weaves the threads of time around the target, giving them some of the benefits of a day's passage. The target decreases the values of any and conditions it has by 1 and can immediately attempt one saving throw against each affliction it has with a stage length of 1 day or less. The target is then temporarily immune for 1 day.","source":{"provider":"PAIZO","sourceId":"pCvJ4yoZJxDtgUMI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.resurrect","name":"Resurrect","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["healing"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"gemstones worth a total value of 75 gp × the target's level"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 dead creature of up to 10th level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert)","secondaryChecks":"Medicine, Society","secondaryCasters":2},"description":"You attempt to call forth the target's soul and return it to its body. This requires the target's body to be present and relatively intact. The target must have died within the past year. If has decided that the target's time has come or the target doesn't wish to return, this ritual automatically fails, but you discover this after the successful Religion check and can end the ritual without paying the cost.\n\nCritical Success You resurrect the target. They return to life with full Hit Points and the same spells prepared and points in their pools they had when they died, and still suffering from any long-term debilitations of the old body. The target meets an agent of their deity during the resurrection who inspires them, granting them a +1 status bonus to attack rolls, Perception, saving throws, and skill checks for 1 week. The target is also permanently changed in some way by their time in the afterlife, such as gaining a slight personality shift, a streak of white in the hair, or a strange new birthmark.\n\nSuccess As critical success, except the target returns to life with 1 Hit Point and no spells prepared or points in any pools, and still is affected by any long-term debilitations of the old body. Instead of inspiring them, the character's time in the Boneyard has left them temporarily debilitated. The target is Clumsy 1, Drained 1, and Enfeebled 1 for 1 week; these conditions can't be removed or reduced by any means until the week has passed.\n\nFailure Your attempt is unsuccessful.\n\nCritical Failure Something goes horribly wrong-an evil spirit possesses the body, the body transforms into a special kind of undead, or some worse fate befalls the target.\n\nHeightened (6th) You can resurrect a target of up to 12th level, and the base cost is 125 gp.\n\nHeightened (7th) You can use resurrect even with only a small portion of the body; the ritual creates a new body on a success or critical success. The target must have died within the past decade. The ritual requires four secondary casters, each of whom must be at least half the target's level. The target can be up to 14th level, and the base cost is 200 gp.\n\nHeightened (8th) As 7th rank, but the target can be up to 16th level and the base cost is 300 gp.\n\nHeightened (9th) You can use resurrect even without the body as long as you know the target's name and have touched a portion of its body at any time. The target must have died within the past century, and it doesn't gain the negative conditions on a success. The ritual requires eight secondary casters, each of whom must be at least half the target's level. The target can be up to 18th level, and the base cost is 600 gp.\n\nHeightened (10th) As 9th rank, except it doesn't matter how long ago the target died. The ritual requires 16 secondary casters, each of whom must be at least half the target's level. The target can be up to 20th level, and the ritual's base cost is 1,000 gp.","source":{"provider":"PAIZO","sourceId":"kqhPt9344UkcGVYO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.return-beacon","name":"Return Beacon","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a unique planar beacon somewhere within the spell's range that remains in place. The beacon is invisible except when detected by detect magic, in which case it looks like a 10-foot-wide tower of bright light stretching into the sky. At any time during the duration of the beacon, you can complete a 1-minute activity, which has the concentrate and manipulate traits, to focus on the beacon and transport yourself and any items you're wearing and holding from your current space to the location of the beacon. Transporting yourself in this way ends the spell. If this would bring another creature with you-even if you're carrying it in an extradimensional container-the beacon collapses, ending the spell, and the transportation attempt fails.\n\nCasting return beacon while a beacon is active causes the previous return beacon spell to end. If you are not within 1 mile of the beacon, your attempt to transport yourself to the beacon fails. If a solid object is in the same space as the beacon when you transport yourself, you arrive in the nearest open space to the beacon. If there is not an open space within 30 feet of the beacon, your attempt to transport yourself fails, but the beacon remains intact.\n\nHeightened (7th) The duration is 8 hours and you can transport yourself to the beacon from up to 100 miles away.\n\nHeightened (8th) The duration is 24 hours and you can transport yourself to the beacon from up to 1,000 miles away. In addition, you can bring 1 willing ally you touch with you when you transport to the beacon.\n\nHeightened (9th) The duration is 1 week and you can transport yourself to the beacon from anywhere on the same plane. In addition, you can bring up to 4 willing allies you touch with you when you transport to the beacon.\n\nHeightened (10th) The duration is unlimited and you can transport yourself to the beacon from any distance, even across other planes. In addition, you can bring up to 8 willing allies you touch when you transport to the beacon.","source":{"provider":"PAIZO","sourceId":"ru3YdXajUREbKQDV","book":"Pathfinder #166: Despair on Danger Island","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rewinding-step","name":"Rewinding Step","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You anchor your location in time so that you can swiftly retrace your steps later with complex chronomancy. The space you're in when you cast the spell becomes your temporal anchor space. While you're within 500 feet of your temporal anchor space, you can spend a single action that has the concentrate trait to instantaneously return to that space (you don't need to have line of effect to the space). The spell then ends. You bring any items that are in your possession with you when you take the action to return.\n\nIf the anchor space is occupied when you attempt to return to it or if this spell would bring another creature with you, the spell fails to transport you, then ends.\n\nHeightened (7th) You can return if you're within 1,000 feet of your anchor space.\n\nHeightened (9th) You can return if you're within 1 mile of your anchor space.","source":{"provider":"PAIZO","sourceId":"5tpk4Q2QI3FVhm99","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rewrite-possibility","name":"Rewrite Possibility","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","fortune","manipulate","mental","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You continually glimpse into the target's future and nudge fate to guide them toward the best possible outcome. Due to the amount of information this spell requires you to process, you can't have more than one rewrite possibility spell in effect at a time. Casting it again ends the previous casting. While rewrite possibility is in effect, the target gains a +1 status bonus to initiative rolls. In addition, you gain the following reaction.\n\nRewrite Possibility r\n\nTrigger The target fails a check\n\nEffect The target rolls again with a +2 status bonus and uses the higher result.","source":{"provider":"PAIZO","sourceId":"BAu5AgqoO556clyK","book":"Pathfinder Stolen Fate Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rip-the-spirit","name":"Rip the Spirit","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["death","void"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"5d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You supernaturally rip the spirit from a living creature's body, dooming the target to pain and death. The target takes 5d6 void damage, depending on its basic Fortitude save, and is Drained 1 if it fails its save. The spell's effect is based on how many actions you spend when Casting the Spell.\n\n1 (somatic) The spell targets one living creature in range.\n\n2 (somatic, verbal) The spell targets one living creature in range and the damage is 10d6[void] damage instead of 5d6.\n\n3 (material, somatic, verbal) The spell targets all living creatures in a 30-foot emanation.\n\nHeightened (+1) The amount of damage increases by 1d6, or by [[/r 2d6]] for the 2-action version.","source":{"provider":"PAIZO","sourceId":"1bw6XJMOERcbC5Iq","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ritual-obstruction","name":"Ritual Obstruction","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":60}},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You establish a zone of magical feedback that makes it impossible to succeed at rituals of this spell's rank or lower in the area. Ritual obstruction ignores all cover, including walls and ceilings, to the extent of its area. Anyone attempting to cast a ritual within the area knows, when they begin to cast the ritual, the area is cursed to impede rituals. Any ritual cast in the area can't have a final result better than failure.","source":{"provider":"PAIZO","sourceId":"h7h0wMxu4WOpveQ3","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sawtooth-terrain","name":"Sawtooth Terrain","kind":"SPELL","rank":5,"rarity":"RARE","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"e72ZbHgzdvNBKkL2","formula":"3d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"e72ZbHgzdvNBKkL2":"3d6"}},"counteraction":false,"ritual":null,"description":"You cause long, serrated mantis limbs to appear, swiping at and obstructing creatures in the area. The area is difficult terrain. Each creature in the area when the spell is cast and who end their turn within the area take 3d6 slashing damage and (floor((@item.level -1)/2)d6)[bleed] damage, as determined by its Reflex save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and no persistent damage.\n\nFailure The creature takes full damage and a –10-foot circumstance penalty to their Speed until they receive magical healing or benefit from a successful Medicine check against your spell DC to .\n\nCritical Failure The creature takes double damage and a –15-foot circumstance penalty to their Speed until they receive magical healing or benefit from a successful Medicine check against your spell DC to administer First Aid.\nHeightened (+2) The damage increases by 3d6, and the persistent bleed damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"I2IgZu4Rd2dz0J6v","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.scouring-pulse","name":"Scouring Pulse","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","light","manipulate","vitality"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"8lhfdml2dfwh0pc1","formula":"6d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Area 10-foot radius, 60-foot-tall cylinder\nYou inundate the area with concentrated vitality energy, which scours away the stain of undeath. Each creature in the area takes 6d8 vitality damage and must attempt a basic Reflex save. Creatures that fail the save also take (ternary(gte(@item.level,5),1,2))d8[persistent,vitality] damage. Creatures that take persistent vitality damage from scouring pulse are wreathed in a heatless halo of light. They emit bright light in a 5-foot radius preventing them from being ; if the creature is , they're concealed while affected by scouring pulse, rather than being undetected.\nHeightened (8th) The vitality damage increases to 9d8 damage, and the persistent vitality damage increases to 2d8 persistent vitality damage. Creatures remain suffused in light for [[/r 1d4 #Rounds]]{1d4 additional rounds} after removing the persistent vitality damage.","source":{"provider":"PAIZO","sourceId":"9bOqFkewRz7Z3HZ5","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.scouting-eye","name":"Scouting Eye","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TEXT","text":"see text"},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an , floating eye, 1 inch in diameter, at a location you can see within 500 feet. It sees in all directions with your normal visual senses and continuously transmits what it sees to you.\n\nThe first time you Sustain the spell each round, you can either move the eye up to 30 feet, seeing only things in front of the eye, or move it up to 10 feet, seeing everything in all directions around it. There is no limit to how far from you the eye can move, but the spell ends immediately if you and the eye ever cease to be on the same plane of existence. You can attempt Seek actions through the eye if you want to attempt Perception checks with it. Any damage dealt to the eye destroys it and ends the spell.","source":{"provider":"PAIZO","sourceId":"Ek5XI0aEdZhBgm21","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.secret-chest","name":"Secret Chest","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 container and its contents, totaling 10 Bulk or less","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You banish a container and its contents to the Ethereal Plane, where you can retrieve it from later. The container's physical properties-the material from which it is made, any locks, or other features-are irrelevant to the casting of this spell, but the container can't contain any creatures. When you Cast this Spell, the container and all its contents are transported to a random location deep in the Ethereal Plane. Time passes normally for the container and its contents, and the environmental effects of the Ethereal Plane apply to it. Though very unlikely, it's possible for a creature on the Ethereal Plane to stumble upon the chest.\n\nYou can the spell to return the chest to your current location. If the spell ends by any other means, the container is lost on the Ethereal Plane and you can no longer recall it with this spell, though you could search for it in other ways.","source":{"provider":"PAIZO","sourceId":"BoA00y45uDlmou07","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sending","name":"Sending","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"planetary"},"target":"1 creature you know well","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send the creature a mental message of 25 words or fewer, and it can respond immediately with its own message of 25 words or fewer.","source":{"provider":"PAIZO","sourceId":"R9xqCBblkS5KE4y7","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-blast","name":"Shadow Blast","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","shadow"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"varies"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area varies\n\nDefense reflex or will (target's choice)\nYou shape the shadow substance of the Netherworld into a blast. Choose (@item.rank+1)d8[acid|options:area-damage], (@item.rank+1)d8[bludgeoning|options:area-damage], (@item.rank+1)d8[cold|options:area-damage], (@item.rank+1)d8[electricity|options:area-damage], (@item.rank+1)d8[fire|options:area-damage], (@item.rank+1)d8[force|options:area-damage], (@item.rank+1)d8[piercing|options:area-damage], (@item.rank+1)d8[slashing|options:area-damage], (@item.rank+1)d8[sonic|options:area-damage], or (@item.rank+1)d8[spirit|options:area-damage] damage, and choose a , a within 120 feet, or a . The blast deals 6d8 damage of the type you chose to each creature in the area.\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"IqJ9URobmJ9L9UBG","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-jump","name":"Shadow Jump","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","shadow","teleportation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You are in dim light or darkness"},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You instantly transport yourself from one shadow to another. Teleport yourself and any items you're wearing and holding from your current space to a clear space you can see that's in dim light or darkness and within range. You can transport your familiar with this spell, but if shadow jump would bring any other creature with you-even if you're carrying the creature in an extradimensional container-the spell is disrupted.\n\nHeightened (8th) When you arrive at your destination, you can become until the end of your next turn or until you are no longer in an area of dim light or darkness, whichever comes first. The invisibility is an illusion effect.","source":{"provider":"PAIZO","sourceId":"5ttAVJbWg2GVKmrN","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-siphon","name":"Shadow Siphon","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","illusion","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering spell","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Trigger A spell or magical effect deals damage.\nExchanging material energy with that of the Shadow Plane, you transform the triggering spell into a partially illusory version of itself. Attempt to counteract the target spell. If the attempt is successful, any creatures that would be damaged by the spell instead take only half as much damage, but the spell otherwise works as normal. Treat shadow siphon's counteract rank as 2 higher for this attempt.","source":{"provider":"PAIZO","sourceId":"tcwT97RWKxsJiefG","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shall-not-falter-shall-not-rout","name":"Shall not Falter, Shall not Rout","kind":"SPELL","rank":5,"rarity":"RARE","traits":["concentrate","focus","healing"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Calling out the fifth line of the Crimson Oath, you seal your most grievous injuries with a stroke of your blade. The first time each round that you Strike with your weapon and deal damage to a foe, you recover a number of HP equal to twice shall not falter, shall not rout's level. This healing can't raise your current HP above half of your maximum HP.","source":{"provider":"PAIZO","sourceId":"rnFAHvKpcsU4BJD4","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shepherd-of-souls","name":"Shepherd of Souls","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","sorcerer"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You stay the hand of fate for one not yet destined to die, sacrificing some of your own vitality to heal them.\n\nYou lose up to 15 Hit Points as a sacrifice, and the target reduces the damage by twice the number of Hit Points sacrificed. If this reduction exceeds the amount of damage, the target recovers Hit Points equal to the excess amount.\n\nHeightened (+2) The maximum number of Hit Points you can sacrifice increases by 5.","source":{"provider":"PAIZO","sourceId":"SzKkzq3Rr6vKIxbp","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shock-and-awe","name":"Shock and Awe","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["auditory","concentrate","emotion","fear","illusion","manipulate","mental","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":50}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create the illusion of cannons exploding, bullets and arrows flying, and magical ballistics firing, as an overwhelming torrent of information, both visual and auditory. Enemies in the area must attempt a Will save.\nCritical Success The enemy is unaffected.\n\nSuccess The target is Frightened 1.\n\nFailure The enemy is Frightened 2 and Stunned 1.\n\nCritical Failure The enemy is Frightened 3 and Stunned 2.","source":{"provider":"PAIZO","sourceId":"Y3qZrvZrqPuGJ2hk","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.slither","name":"Slither","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"hBNB5kWrMV8T2CuH","formula":"3d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false},{"id":"mY0vhGfbdzA69pIz","formula":"1d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"hBNB5kWrMV8T2CuH":"0","mY0vhGfbdzA69pIz":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A mass of snakes made of shadow rise up to capture creatures in the area. Each creature in the area when you Cast the Spell takes 3d6[piercing] damage and 1d6[persistent,poison] damage from a biting snake, and it's or depending on its Reflex save. A creature that ends its turn in the area must also attempt this save, even if it's already grabbed or restrained by the snakes. You can Dismiss the spell.\n\nSuccess The creature is unaffected.\n\nFailure The creature takes full damage and is grabbed by a snake. The snakes' DC is equal to your spell DC. A creature can attack a snake to release the creature. A snake's AC is equal to your spell DC, and it's destroyed if it takes 12 or more damage at once. New snakes continually regrow as long as the spell lasts, so destroying snakes doesn't prevent slither from capturing more creatures.\n\nCritical Failure As failure, but the creature takes double damage and is restrained by a snake.\n\nHeightened (+2) The persistent poison damage increases by 1d6 and snake HP increases by 6.","source":{"provider":"PAIZO","sourceId":"xFp4EwVcYwSG336t","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.soulshelter-vessel","name":"Soulshelter Vessel","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","good","healing","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature and 1 non-magical stone object of 1 or 2 Bulk","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You connect the spirit of the target creature with the target object, giving their spirit a durable vessel that protects and empowers their body. You create a pool of healing within the object, which starts out with 40 HP worth of healing per Bulk of the object. (These HP can only be used by the creature, and don't increase the object's HP.) When you Cast the Spell, the targeted creature regains 10 HP, which come out of the object's pool. You can also spend a single action-which has the concentrate, good, healing, necromancy, and vitality traits-to repeat this transfer. When the pool is empty, the object becomes broken. The spell ends if the object becomes broken or the targets are no longer within 500 feet of each other.\n\nIf the target creature would be reduced to 0 Hit Points, the creature regains either 20 HP or the amount left in the object's pool, whichever is lower. The object immediately becomes broken, ending the spell.\n\nHeightened (+2) Increase the maximum Bulk of the item by 1 (potentially increasing the size of the healing pool), the amount of HP exchanged each time the stone is used by 5, and the amount of HP exchanged when the creature would be reduced to 0 HP by 10 (or by the amount left in the pool, if it's lower).","source":{"provider":"PAIZO","sourceId":"wYSLTNvmxbe78l2c","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.speak-with-stones","name":"Speak with Stones","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can ask questions of and receive answers from natural or worked stone. While stone is not intelligent, you speak with the natural spirits of the stone, which have a personality colored by the type of stone, as well as by the type of structure the stone is part of, for worked stone. A stone's perspective, perception, and knowledge give it a worldview different enough from a human's that it doesn't consider the same details important. Stones can mostly answer questions about creatures that touched them in the past and what is concealed beneath or behind them.\n\nHeightened (6th) The duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"YIMampGpij4Y30yE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spectral-advance","name":"Spectral Advance","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["champion","concentrate","focus","polymorph","spirit"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 or 2"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Taking on a spiritual form, you flash across the battlefield to engage an enemy. You Stride to a space adjacent to an enemy. If you cast the spell using 2 actions, you can Stride twice instead of once. If you have a fly Speed, you can Fly instead of Striding.\n\nIf you're mounted, you can have your mount move instead of you. Movement from spectral advance doesn't trigger reactions and ignores difficult terrain and greater difficult terrain. During the movement, you (or your mount) have resistance equal to your level to all damage.","source":{"provider":"PAIZO","sourceId":"VNAOHrWhNYX3jKdy","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spellmasters-ward","name":"Spellmaster's Ward","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create one or more glowing protective runes that revolve around you. For each additional action you use when Casting the Spell, increase the number of runes you create by one, to a maximum of three runes for 3 actions.\n\nWhen you next take damage from a spell, a rune is expended to prevent 2d6 + (@item.rank - 5)[untyped] of that spell's damage. If damage from the triggering spell remains, additional runes are expended until the damage is completely negated, or until all runes have been spent, whichever comes first.\nHeightened (+1) Each rune prevents an additional 1 damage.","source":{"provider":"PAIZO","sourceId":"VrhCpCIQB8PFax77","book":"Pathfinder Lost Omens Pathfinder Society Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spiritual-guardian","name":"Spiritual Guardian","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d8","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"A Medium guardian made of magical force appears in an unoccupied space in range. The spiritual guardian is translucent and wields a ghostly echo of one weapon you're wielding or wearing. If you have a deity, the guardian takes the form of one of your deity's attendants or servitors. If you sanctify the spell, the guardian's attacks are sanctified as well.\n\nCreatures can move through the guardian's space but can't end their movement in it. You and your allies can flank with the guardian. The guardian doesn't have any other attributes a creature would normally have, aside from 50 Hit Points that it can't recover by any means and that it can lose only when protecting a creature (see below).\n\nWhen you Cast the Spell and each time you Sustain it, you can have the guardian move to any unoccupied space within 120 feet of you and either attack or protect.\n\n- Attack The guardian makes a melee spell attack against an adjacent creature, dealing 3d8 damage on a hit (or double damage on a critical hit). The damage type is the same as the chosen weapon (or any of its types for a versatile weapon). The attack deals spirit damage instead if that would be more detrimental to the creature (as determined by the GM). This attack uses and contributes to your multiple attack penalty.\n\n- Protect The guardian protects a creature of your choice. Each time the chosen creature would take damage and the guardian is adjacent to it, the guardian takes the first 10 damage instead of the ally. This protection lasts until you command the guardian to attack or to protect a different creature, or the guardian is destroyed.\n\nHeightened (+2) The guardian's damage increases by 1d8, and its Hit Points increase by 20.","source":{"provider":"PAIZO","sourceId":"jQdm301h6e8hIY4U","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spiritual-torrent","name":"Spiritual Torrent","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"lI9EQaXqSWU8wuZI","formula":"10d6","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"lI9EQaXqSWU8wuZI":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You release your spiritual essence in a torrential blast of energy, dealing 10d6 damage. If you're a living creature, this spell deals vitality damage and gains the vitality trait. If you're an undead creature, this spell deals void damage and gains the void trait. The spell's effect is based on how many actions you spend when Casting the Spell.\n\n2 (somatic, verbal) The spell targets all creatures in a 60-foot line.\n\n3 (material, somatic, verbal) The spell targets all creatures in a 60-foot cone.\n\nHeightened (+1) The spell's damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"Y1YysjZ40ft0aLFN","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spiritual-transport","name":"Spiritual Transport","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":240},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon the spiritual energies surrounding you to teleport you to an unoccupied space within range that you can see. Any items you're wearing and holding come with you. Your familiar or animal companion, if you have one that's sharing your space or adjacent to your space, is transported with you, but any other creature sharing your space remains in that space.\nHeightened (7th) The range increases to 1 mile. You don't need to be able to see your destination, as long as you have been there in the past and know its relative direction from you.","source":{"provider":"PAIZO","sourceId":"6o75SEEYjdaMDkoG","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stagnate-time","name":"Stagnate Time","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You examine the time stream in a particular area, then proceed to stick a few metaphorical pins into it, thickening and slowing down the flow of time until it rumbles along like a river of molasses. Any creature that begins its turn in the area must attempt a Will save.\nSuccess The creature is unaffected.\n\nFailure The creature is Slowed 1 this turn.\n\nCritical Failure The creature is Slowed 2 this turn.","source":{"provider":"PAIZO","sourceId":"3E1p58MNQMO4GAxt","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.steal-the-sky","name":"Steal the Sky","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["air","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"target":"the creature you hit","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You make a successful unarmed Strike against a flying creature.\n\nYou deny a flying creature the support of the air.\n\nCritical Success The creature is unaffected.\n\nSuccess The target descends 60 feet. If it hits a surface, it takes bludgeoning damage as if it had fallen.\n\nFailure As success; if the target hits a surface, it falls and can't Fly, levitate, or otherwise leave the ground for 1 minute.\n\nCritical Failure As failure, and the creature takes double damage from hitting a surface.\n\nHeightened (+1) Increase the distance the creature must descend by 20 feet.","source":{"provider":"PAIZO","sourceId":"zoY0fQYTF1NzezTg","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.stormburst","name":"Stormburst","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","electricity","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"j69kf1nfy3b1xton","formula":"6d6","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your voice projects like cracking thunder as you summon a localized storm, creating a fearsome surge of lightning and wind that deals 6d6 electricity damage. Each creature must attempt a Reflex saving throw.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is knocked .\n\nCritical Failure The creature takes double damage, is knocked prone, and is Stunned 1.\n\nHeightened (7th) The damage increases to 8d6, and targets who critically fail are Stunned 2.\n\nHeightened (9th) The damage increases to 10d6, and targets who critically fail are Stunned 3.","source":{"provider":"PAIZO","sourceId":"Ifc2b6bNVdjKV7Si","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.strange-geometry","name":"Strange Geometry","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"CUBE","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 4 cubes, each 10 feet on a side\n\nYou cause the areas to appear to swell, bend, and break, twisting together in a bizarre spatial geometry. The cubes of the spell's area can't be adjacent to one another. A creature must attempt a Will save if it's in one of the cubes when you Cast the Spell, or if it later enters one of the areas, with the following effects. A creature interacting with the illusion can also attempt a Will save to disbelieve the illusion, as normal.\nSuccess The creature disbelieves the illusion.\n\nFailure All terrain in the cubes is difficult terrain for the creature, including the air if the creature is flying, walls if it's climbing, and so on. When the creature would exit one of the cubes, it exits from one randomly determined by the GM. This is a teleportation effect. It can exit from any edge of that cube it chooses. When selecting a random cube, the GM excludes any that don't match the creature's terrain; for instance, if the creature were exiting along the ground, the GM would exclude any cube that didn't have an exit on the ground.","source":{"provider":"PAIZO","sourceId":"m4Mc5XbdML92BKOE","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.subconscious-suggestion","name":"Subconscious Suggestion","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","incapacitation","linguistic","manipulate","mental","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You implant a subconscious suggestion deep within the target's mind for them to follow when a trigger you specify occurs. You suggest a course of action to the target. Your directive must be phrased in such a way as to seem like a logical course of action to the target, and it can't be self-destructive or obviously against the target's self-interest. The target must attempt a Will save.\n\nCritical Success The target is unaffected and knows you tried to control it.\n\nSuccess The target is unaffected and thinks you were talking to them normally, not casting a spell on them.\n\nFailure The suggestion remains in the target's subconscious until the next time you prepare. If the trigger occurs before then, the target immediately follows your suggestion. The effect has a duration of 1 minute, or until the target has completed a finite suggestion or the suggestion becomes self-destructive or has other obvious negative effects.\n\nCritical Failure As failure, but the duration is 1 hour.\n\nHeightened (9th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"GP3wewkQXEPrLxYj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summerland-spell","name":"Summerland Spell","kind":"RITUAL","rank":5,"rarity":"UNIQUE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"1,000 gp worth of precious stones ground to dust"},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"BURST","feet":5280}},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Performance, Religion, Society, Mammoth Lord Lore or a similar Lore skill, Survival","secondaryCasters":5},"description":"The Summerland Spell is an extension of a unique ritual developed by Brogan the Grasswalker. The ritual dramatically dampens harsh weather around Hillcross, causing the temperature of the area to move up to two categories closer to normal. As a result, autumns and winters are far less brutal around Hillcross, while spring and summer months are practically mild and pleasant.\n\nThe ritual as presented is lower rank, easier to cast, and much less dangerous to the casters than the original version cast by Brogan the Grasswalker because it simply extends the original ritual's effects over Hillcross. A character who wishes to duplicate the effects somewhere else would need to develop a unique 10th-rank ritual with a 5th-rank ritual to extend the duration, as Brogan did, and then find someone willing to cast the deadlier initial ritual.\n\nCritical Success The ritual takes effect normally, continuing the duration for 1 more year.\n\nSuccess The ritual takes effect normally, continuing the duration for 1 more year, but the primary caster is Drained 1. If the primary caster was already drained, increase the value of the drained condition by 1. This drained condition is a curse effect and is permanent until counteracted with remove curse or similar magic.\n\nFailure The ritual fails.\n\nCritical Failure The ritual fails. The primary caster is Drained 2, and the secondary casters are drained 1 (increasing the value of any drained condition they already have). This drained condition is a curse effect and is permanent until counteracted with remove curse or similar magic.","source":{"provider":"PAIZO","sourceId":"aVqsE5OedOwdHQvF","book":"Pathfinder #177: Burning Tundra","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-anarch","name":"Summon Anarch","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a chaotic celestial, monitor, or fiend to fight on your behalf. You summon a common chaotic creature that has the celestial, monitor, or fiend trait and whose level is 5 or lower. You can't summon a creature unless its alignment is one of your deity's preferred alignments (or, if you don't have a deity, is within one step of your alignment). At the GM's discretion, some deities might restrict specific types of creatures, even if their alignments match. Heightening the spell increases the maximum level of creature you can summon.\n\nHeightened (6th) Level 7.\n\nHeightened (7th) Level 9.\n\nHeightened (8th) Level 11.\n\nHeightened (9th) Level 13.\n\nHeightened (10th) Level 15.","source":{"provider":"PAIZO","sourceId":"n8ckecJpatSBEp7M","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-axiom","name":"Summon Axiom","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a lawful celestial, monitor, or fiend to fight on your behalf. You summon a common lawful creature that has the celestial, monitor, or fiend trait and whose level is 5 or lower. You can't summon a creature unless its alignment is one of your deity's preferred alignments (or, if you don't have a deity, is within one step of your alignment). At the GM's discretion, some deities might restrict specific types of creatures, even if their alignments match. Heightening the spell increases the maximum level of creature you can summon.\n\nHeightened (6th) Level 7.\n\nHeightened (7th) Level 9.\n\nHeightened (8th) Level 11.\n\nHeightened (9th) Level 13.\n\nHeightened (10th) Level 15.","source":{"provider":"PAIZO","sourceId":"ba12fO37w7O37gim","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-celestial","name":"Summon Celestial","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the celestial trait and whose level is 5 or lower to fight for you. The GM might determine your deity restricts the specific types of celestials you can summon in certain cases. For instance, Calistria doesn't typically allow her followers to summon aeons.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"lTDixrrNKaCvLKwX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-dragon","name":"Summon Dragon","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the dragon trait and whose level is 5 or lower to fight for you. If the dragon has a magical tradition trait (arcane, divine, occult, or primal), you can summon it only if you're using that tradition to cast summon dragon.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"kghwmH3tQjMIhdH1","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-entity","name":"Summon Entity","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the aberration trait and whose level is 5 or lower to fight for you.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"i1TvBID5QLyXrUCa","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-fiend","name":"Summon Fiend","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon","unholy"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the fiend trait and whose level is 5 or lower to fight for you. The GM might determine your deity restricts the specific types of fiends you can summon in certain cases. For instance, archdevils typically allow their followers to summon devils, but not other fiends.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"29ytKctjg7qSW2ff","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-giant","name":"Summon Giant","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the giant trait and whose level is 5 or lower to fight for you.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"e9UJoVYUd5kJWUpi","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summon-healing-servitor","name":"Summon Healing Servitor","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","healing","incarnate","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"SvxMj89z9Ze4Na3e","formula":"3d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"SvxMj89z9Ze4Na3e":"1d8"}},"counteraction":false,"ritual":null,"description":"You call forth a servitor forged from raw vitality energy to heal and bolster your allies. The servitor occupies the space of a Huge creature and has a speed of 60 feet.\n\nArrive (healing, necromancy, vitality) Servitor's Protection The servitor appears in a flash of light, moving from ally to ally and granting them a temporary reprieve. All allies within 20 feet of the Servitor gain 20 temporary Hit Points until the servitor departs.\n\nDepart (healing, necromancy, vitality) Servitor's Blessing The servitor disappears in a of vitality energy. All willing living creatures within heal 3d8 Hit Points. All undead within take that much damage, with a basic Fortitude save.\n\nHeightened (+2) The Arrive effect's temporary Hit Points increase by 8, and the Depart effect's healing and damage to undead increase by 1d8.","source":{"provider":"PAIZO","sourceId":"3r897dYO8oYvuyn5","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.summon-monitor","name":"Summon Monitor","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the monitor trait and whose level is 5 or lower to fight for you. The GM might determine your deity restricts the specific types of monitors you can summon in certain cases. For instance, Urgathoa typically doesn't allow her followers to summon psychopomps.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"ZbEHglw5tkJ3grQZ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.symphony-of-the-unfettered-heart","name":"Symphony of the Unfettered Heart","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"you or 1 ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":true,"ritual":null,"description":"Your symphony lifts listeners from their worldly concerns. Attempt a Performance check to counteract an effect applying one of the following conditions to the target: , , , , , or . If you fail, you can't target the same effect on the target for 1 day. Use the condition's source to determine the counteract DC (for example, the DC for grabbed).\n\nHeightened (9th) You can target up to four creatures.","source":{"provider":"PAIZO","sourceId":"ZAX0OOcKtYMQlquR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.synaptic-pulse","name":"Synaptic Pulse","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You emit a pulsating mental blast that penetrates the minds of all enemies in the area. Each enemy in the area must attempt a Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is Stunned 1.\n\nFailure The creature is Stunned 2.\n\nCritical Failure The creature is Stunned for 1 round.","source":{"provider":"PAIZO","sourceId":"BilnTGuXrof9Dt9D","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.synesthesia","name":"Synesthesia","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target's senses are suddenly rewired in unexpected ways, causing them to process noises as bursts of color, smells as sounds, and so on. This has three effects, and the target must attempt a Will save.\n- Due to the distraction, the target must succeed at a flat each time it uses a concentrate action, or the action fails and is wasted.\n- The target's difficulty processing visual input makes all creatures and objects from it.\n- The creature has trouble moving, making it Clumsy 3 and giving it a –10-foot status penalty to its Speeds.\n\nCritical Success The target is unaffected.\n\nSuccess The target is affected for 1 round.\n\nFailure The target is affected for 1 minute.\n\nCritical Failure As failure, and the target is Stunned 2 as it attempts to process the sensory shifts.\nHeightened (9th) You can target up to five creatures.","source":{"provider":"PAIZO","sourceId":"OAt2ZEns1gIOCgrn","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.telekinetic-haul","name":"Telekinetic Haul","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 unattended object of up to 80 Bulk with no dimension longer than 20 feet","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You move the target up to 20 feet, potentially suspending it in midair. When you Sustain the Spell, you can do so again, or you can shift your telekinetic focus to a different eligible target within range, moving it instead.","source":{"provider":"PAIZO","sourceId":"tpLTLbJUrYcMWGld","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.telepathic-bond","name":"Telepathic Bond","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"you and up to 4 willing creatures touched","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The targets can communicate telepathically with any or all of the other targets from any point on the same planet.","source":{"provider":"PAIZO","sourceId":"gfVXAW95YWRz0pJC","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.temporary-glyph","name":"Temporary Glyph","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 5-foot square\n\nYou temporarily bind a hostile spell into a symbol. While Casting this Spell, you also Cast a Spell of a lower spell rank to store in the glyph. The stored spell must take 2 actions or fewer to Cast, have a hostile effect, and target one creature or have an area. Any creature that enters temporary glyph's area activates the glyph, releasing the harmful spell within. You can set a password for the glyph. Speaking it when entering the spell's area prevents the glyph from triggering. You can also set a more specific trigger to limit which types of creatures set off the glyph.\n\nOnce a spell is stored in the glyph, the glyph gains all the traits of that spell. If the stored spell can target one or more creatures, it targets the creature that set off the glyph. If it has an area, that area is centered on the creature that set off the glyph. Temporary glyph's duration ends when the glyph is triggered. The glyph is a magical trap, using your spell DC for both the Perception check to notice it and the Thievery check to disable it; both checks require the creature attempting them to be trained in order to succeed.\n\nYou can Dismiss temporary glyph.","source":{"provider":"PAIZO","sourceId":"YWuyjhWbdoTiA1pw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.terrain-transposition","name":"Terrain Transposition","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","ranger","teleportation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":90},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You mystically transpose your current location with another. While in a wilderness environment, you transport yourself and items you're holding to a clear space you can see within range. If you have and both your starting and ending position are in your favored terrain, the range increases to 180 feet. If you have an animal companion and it is adjacent to you, you can transport it along with you to an adjacent open space, but if this spell would bring any other creature with you, even in an extradimensional container, the spell is lost.","source":{"provider":"PAIZO","sourceId":"rtA3HRGoy7PQTOhq","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tesseract-tunnel","name":"Tesseract Tunnel","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","psychic","teleportation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You race from point to point, tearing open a tunnel in space. You create a portal in your current space and then Stride, creating another portal in the space you end your . Until the beginning of your next turn, any creature that enters the first portal can immediately transport itself to the exit portal as part of its move action, which adds the teleportation trait to its movement.\n\nYou can have only one tesseract tunnel open at a time; creating another causes the first to immediately close. You can use tesseract tunnel while Burrowing, Climbing, Flying, or Swimming instead of Striding if you have the corresponding movement type.","source":{"provider":"PAIZO","sourceId":"Z1MoMTcgFQiCI90t","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.the-worlds-a-stage","name":"The World's a Stage","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["fortune"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"costumes and a stage large enough to fit all casters"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 month","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Crafting, Performance","secondaryCasters":0},"description":"This famous ritual is a sophisticated example of symbolic magic, binding fate and fortune to follow a prepared script. To conduct the ritual, you and the secondary casters must put on a long-form, multi-person, plot-based performance that's usually a play or opera, though more unusual performances have been known. You take the role of the director, while the secondary casters are either actors (Performance) or significant backstage figures, such as set or costume designers (Crafting). The casting time of the ritual includes both preparations and rehearsals of various sorts and the actual performance, which must be at least an hour long.\n\nThe performance presents current events and offers a particular vision on how they resolve, often in metaphorical or allegorical format (proposing the overthrow of a tyrant by referring to a different, legendary tyrant who was overthrown, or suggesting that a murderous secret might be uncovered by presenting an allegory of truth defeating murder). This performance must be presented to an audience of at least a hundred people, a majority of whom must both be connected, at least peripherally, to the events in question (the people of the tyrant's city, or the residents of the village where the murder occurred) and who must understand what the metaphor or allegory actually refers to. For the magic to spark, the performance must declare its purpose loudly and clearly to the parties most concerned. If a major antagonist featured in the performance is in the audience and the ritual is a success, you get a critical success instead.\n\nCritical Success Something sublime sparks between performance and audience, and destiny conspires to push events in the right direction. You and each secondary caster can reroll up to three skill checks at any point during the duration of the ritual after determining the results, as long as the skill check is connected to ensuring the topic of the performance comes true (to sneak past the tyrant's guards or find the murder weapon, for instance).\n\nSuccess As critical success except the sparks of destiny are weaker, so each caster can reroll only a single skill check.\n\nFailure The ritual has no effect.\n\nCritical Failure The performance is a dramatic and horrendous botch, and fate strikes out at the casters. You and each secondary caster are Doomed 1 for the next month, and this condition can't be removed by anything less than a wish or similarly powerful magic.","source":{"provider":"PAIZO","sourceId":"3DB3F2hIx2dMbX8n","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.toxic-cloud","name":"Toxic Cloud","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","death","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"6d8","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You conjure a poisonous fog. This functions as , except the area moves 10 feet away from you each round. You deal 6d8 poison damage to each breathing creature that starts its turn in the spell's area. You can Dismiss the spell.\n\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"MlpbeZ61Euhl0d60","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.transmute-rock-and-mud","name":"Transmute Rock And Mud","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"CUBE","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 2 adjacent 10-foot cubes\n\nYou warp the structure of earthen material, turning rock into mud or mud into rock. Choose one of these two options when you Cast the Spell.\n\n- Rock to Mud You transform non-magical, unworked, and unattended stone in the area into an equal volume of mud. If you Cast this Spell on a stone floor, it becomes difficult terrain; if the resulting mud is at least 3 feet deep, it is greater difficult terrain, or the creature can try to through it (athletics). If the mud is deep enough that a creature can't reach the bottom, the creature must Swim to move through it. If you Cast this Spell on a ceiling, the falling mud deals 8d6[bludgeoning] damage (reflex save) and spreads out, creating difficult terrain in an area 10 feet larger in radius than the original spell's area. Once the rock is transformed into mud, the mud is non-magical and remains until natural conditions cause it to dry out or otherwise disperse.\n\n- Mud to Rock Mud in the area turns into unworked stone. If creatures are in the mud when it is transformed to stone, they must attempt a reflex saving throw.\n\n- Critical Success The creature escapes the mud and is atop the stone, unaffected.\n\n- Success The creature climbs out of the mud as it turns to rock and is atop the stone.\n\n- Failure The creature is partially stuck in the mud and is for 1 round or until it Escapes, whichever comes first.\n\n- Critical Failure The creature is entirely stuck. It is for 1 round or until it Escapes, whichever comes first.\n\nHeightened (+2) Add an additional 10-foot cube to the area, adjacent to at least one of the other cubes.","source":{"provider":"PAIZO","sourceId":"LzfrBDxxPTiuN7uL","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.truespeech","name":"Truespeech","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target can understand all words regardless of language and also speak the languages of other creatures. When in a mixed group of creatures, each time the target speaks, it can choose a creature and speak in a language that creature understands, even if the target doesn't know what language that is.\n\nHeightened (7th) The duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"SwUiVavHKMWG7t5K","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.umbral-journey","name":"Umbral Journey","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","shadow","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"you and up to 10 willing creatures touched","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You move partially into the Netherworld, using its warped nature to speed your travels. Each hour, you cover roughly as much ground as you normally would in 3 days. The landmarks are vague and symbolic rather than concrete, leaving you within a mile of your intended destination when you Dismiss the spell or its duration ends.","source":{"provider":"PAIZO","sourceId":"rxvS7EMJ7qmexAyA","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unblinking-flame-aura","name":"Unblinking Flame Aura","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","healing"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"You focus your sight inside and call on your inner fire to grant you warmth, steady your vision, and soothe your body. You recover (3*@item.level)[healing]{15 Hit Points}. For the duration, you gain a +2 status bonus on Perception checks and resistance 10 to cold.\n\nHeightened (+1) You recover an additional 3 Hit Points, and the resistance to cold increases by 2.","source":{"provider":"PAIZO","sourceId":"floDCUOSzT0F6r77","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unbreaking-wave-vapor","name":"Unbreaking Wave Vapor","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","water"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You're targeted by an attack made by an attacker you can see.\n\nYou're against the triggering attack and gain a +2 circumstance bonus to AC against it. After the triggering attack is complete, you can Step if the triggering attack hit or Step twice if the triggering attack missed.","source":{"provider":"PAIZO","sourceId":"ZQk2cGBCkATO25w0","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.unfolding-wind-buffet","name":"Unfolding Wind Buffet","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["air","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround your unarmed attacks with the speed and force of air. Make three unarmed Strikes against the same target. If at least one was a successful hit, the target must attempt a Fortitude save or be pushed back 5 feet for each normal hit from the buffet, plus 10 feet for each critical hit.\n\nCritical Success The target is unaffected.\n\nSuccess The target is pushed back half the normal distance.\n\nFailure The target is pushed back the normal distance.\n\nCritical Failure The target is pushed back double the normal distance and then knocked .","source":{"provider":"PAIZO","sourceId":"ALuvl9GYawnsZZCx","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.untwisting-iron-roots","name":"Untwisting Iron Roots","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","earth","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"Z0JV5JoCbMHgKA2k","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Z0JV5JoCbMHgKA2k":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You manipulate the earth beneath your feet to throw your enemies off balance, leaving chunks of rock and rubble behind. Creatures within range take 2d6 bludgeoning damage, with a basic Reflex save; on a failed save, they also fall . The affected area becomes difficult terrain, but you can move through the difficult terrain normally.\n\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"9o5aG5025ZczjkPb","book":"Pathfinder Lost Omens Impossible Lands","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.unusual-anatomy","name":"Unusual Anatomy","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["focus","manipulate","polymorph","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You transform your flesh and organs into a bizarre amalgam of glistening skin, rough scales, tufts of hair, and tumorous protuberances. This has three effects:\n\n- You gain resistance 10 to precision damage and resistance 10 to extra damage from critical hits. If the resistance is greater than the extra damage, it reduces the extra damage to 0 but doesn't reduce the attack's normal damage.\n\n- You gain darkvision.\n\n- Acid oozes from your skin. Any creature that hits you with an unarmed attack or with a non-reach melee weapon takes 2d6 acid damage.\n\nHeightened (+2) The resistances increase by 5, and the acid damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"ddKBoCjmSyPSHcws","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.vindicators-judgment","name":"Vindicator's Judgment","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"your hunted prey","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pronounce a terrible judgment upon your quarry that causes all of your attacks and divine spells to strike with deadly efficacy. The target takes extra damage from your attacks, depending on the result of its Fortitude save. The spell ends immediately if the target is no longer your hunted prey.\nCritical Success The target is unaffected.\n\nSuccess The target has weakness 5 to the next Strike you make against it or damaging divine spell you cast that includes it as a target before the end of your next turn.\n\nFailure The target has weakness 5 to all Strikes you make against it or damaging divine spells you cast that includes it as a target for the duration of the spell.\n\nCritical Failure As failure, but the target is against the first Strike or divine spell attack you make against it each round for the duration of the spell.\nHeightened (7th) The weakness is 10.\n\nHeightened (9th) The weakness is 15.","source":{"provider":"PAIZO","sourceId":"VMABZdZyplCKTAAP","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-flesh","name":"Wall of Flesh","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You craft a 20-foot-tall wall of living flesh in a straight line up to 30 feet long. The wall is 3 feet thick, and each 5-foot-long section has AC 10 and 75 Hit Points. If you wish, the wall can be of a smaller length or height. You must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. The wall can't be Repaired but can be healed by vitality, and healing spells and abilities. When you Cast the Spell, choose one of the following features for your wall.\n- Mouths The wall has countless toothy mouths along its surface. The mouths Strike any creature that ends its turn within 5 feet of the wall, using your spell attack modifier for these Strikes and dealing (1+(ceil((@item.level - 4) / 2)))d6[piercing] damage. The mouths are capable of consuming potions; since the wall is alive, it can recover Hit Points from a Healing Potion, but it can't benefit from any effect that would give it the ability to move. Otherwise, the GM determines which potions can affect the wall.\n- Eyes The wall sprouts hundreds of unblinking eyes. You can see through these eyes, gaining a +2 circumstance bonus to visual Perception checks within the wall's line of sight. You can also use the eyes for determining line of sight for ranged attacks and spells, but you don't have line of effect through the wall.\n- Arms The wall is a mass of grasping arms. Any creature that ends its turn within 5 feet of the wall must attempt a Reflex save.\n- Success The creature is unaffected.\n\n- Failure The creature is by the wall for 1 round or until it Escapes against your spell DC, whichever comes first.\n\n- Critical Failure The creature is by the wall for 1 round or until it Escapes against your spell DC, whichever comes first.\n\nHeightened (+2) The Hit Points of each section of the wall increase by 10, and the piercing damage dealt by the wall's mouths increases by 1d6.","source":{"provider":"PAIZO","sourceId":"ZLLY6ThJXCCrO0rL","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wall-of-ice","name":"Wall of Ice","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["cold","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You sculpt an ice barrier that blocks sight and, once shattered, freezes foes. You create either a 1-foot-thick wall of ice in a straight line up to 60 feet long and 10 feet high (the wall doesn't have to be vertical, but it must be anchored on both sides to a solid surface) or a 1-foot-thick, 10-foot radius hemisphere of ice. The ice that makes up the wall is opaque. If you wish, the wall can be of a smaller length, height, or radius.\n\nYou must create the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost. Each 10-foot-by-10-foot section of the wall has AC 10, Hardness 10, and 40 Hit Points, and it's immune to critical hits, cold damage, and precision damage. A section also has weakness 15 to fire; a section of the wall destroyed by fire melts, evaporating into water and steam. A section destroyed by means other than fire leaves behind a chilling mass of ice that is difficult terrain and deals 2d6 cold damage to any creature passing through it.\nHeightened (+2) The Hit Points of each section of the wall increase by 10, and the cold damage dealt to creatures crossing a destroyed section increases by 1d6.","source":{"provider":"PAIZO","sourceId":"R5FHRv7VqyRnxg2t","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.wall-of-stone","name":"Wall of Stone","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shape a wall of solid stone. You create a 1-inch-thick wall of stone up to 120 feet long, and 20 feet high. You can shape the wall's path, placing each 5 feet of the wall on the border between squares. The wall doesn't need to stand vertically, so you can use it to form a bridge or set of stairs, for example. You must conjure the wall in an unbroken open space so its edges don't pass through any creatures or objects, or the spell is lost.\n\nEach 10-foot-by-10-foot section of the wall has AC 10, Hardness 14, and 50 Hit Points, and it's immune to critical hits and precision damage. A destroyed section of the wall can be moved through, but the rubble created from it is difficult terrain.\n\nHeightened (+2) The Hit Points of each section of the wall increase by 15.","source":{"provider":"PAIZO","sourceId":"kOa055FIrO9Smnya","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.waters-of-prediction","name":"Waters of Prediction","kind":"RITUAL","rank":5,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"rare incense and herbs worth a total value of 300 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":20},"target":"1 pool of water","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature or Religion (master, the check has the secret trait)","secondaryChecks":"Nature, Occultism, Religion, or Survival","secondaryCasters":3},"description":"You and the secondary casters peer into the still waters of a natural pool or lake to divine your collective future. Over the course of the minute following the ritual's end, the waters display a scene of one possible future involving the primary caster and as many secondary casters as feasible. This scene is usually, but not necessarily, set within the next few days. The future is unwritten, so the casters would be wise to not read guarantees into the cryptic nature of the visions shown in the water.\n\nCritical Success The scene gives hints as to at least one danger the casters are likely to face, as well as at least one method of effectively addressing the danger (showing the group examining an area of a wall containing a secret hatch to bypass a trap, for example).\n\nSuccess The scene gives a hint as to at least one danger the casters are likely to face, or some cryptic method to effectively address or bypass a danger (such as a scene of lurking trolls, or a scene of the casters lighting several torches and passing them out, but not both).\n\nFailure The scene consists of so many contradictory details that it's impossible to identify a single danger or effective course of action from them.\n\nCritical Failure The scene is wrong; it shows the casters facing a danger they're unlikely to come across, or encourages actions that hinder a likely upcoming encounter (such as encouraging chopping down several trees before meeting an arboreal or a dryad).","source":{"provider":"PAIZO","sourceId":"zaZieDHguhahmM2z","book":"Pathfinder Blog: The Waters of Stone Ring Pond","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wave-of-despair","name":"Wave of Despair","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"1 or more rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You inflict despair on creatures in the area. The effects for each creature are determined by its Will save.\n\nCritical Success The creature is unaffected.\n\nSuccess For 1 round, the creature can't use reactions and must attempt another save at the start of its turn; on a failure, it is Slowed 1 for that turn as it sobs uncontrollably.\n\nFailure As success, but the duration is 1 minute.\n\nCritical Failure As failure, and the creature is automatically slowed 1 for 1 minute.\n\nHeightened (7th) The area increases to a 60-foot cone.","source":{"provider":"PAIZO","sourceId":"GaRQlC9Yw1BGKHfN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.whispers-of-a-dead-goddess","name":"Whispers of a Dead Goddess","kind":"SPELL","rank":5,"rarity":"COMMON","traits":["auditory","concentrate","incapacitation","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"60"},"area":{"shape":"BURST","feet":15}},"duration":{"text":"sustained up to 1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The mysterious whispers that fill the Mordant Spire, which some believe to be the voice of the dead goddess Acavna, become audible. A creature in the area when this Spell is Cast or who enters the area must attempt a Will save.\nCritical Success The creature is unaffected and becomes temporarily immune for 1 hour.\n\nSuccess The target becomes Stunned 1, listening to the whispers.\n\nFailure As success, and the creature will not voluntarily leave the area for 1 round.\n\nCritical Failure As failure, and you can whisper a single course of action to each creature that critically failed, with the effects of suggestion. The effect ends on a creature if you stop sustaining the spell or the creature leaves the area.","source":{"provider":"PAIZO","sourceId":"VehkHHGxQH1jGolN","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wind-jump","name":"Wind Jump","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["air","concentrate","focus","monk"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain a fly Speed equal to your Speed. You must end your turn on solid ground, or you fall.\nHeightened (6th) At the end of your turn, you can attempt a acrobatics check to find purchase in midair. If you succeed, you don't fall.","source":{"provider":"PAIZO","sourceId":"kRxlkPPe6Gr7Du59","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wisdom-of-the-winds","name":"Wisdom of the Winds","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ask a question of the spirits of air, imploring them to send signals through the winds to help you find your way. You might be guided by air elementals, anemoi, or even the Lords of Air themselves. You receive guidance as either words of wisdom or a rustling wind that guides you to a helpful destination—whichever the spirits think will be most beneficial. The spirits don't give guidance you can't follow, such as winds that lead somewhere you can't reach, nor do they give advice that will help their causes at the expense of your own. If you've upset all the spirits of air, they don't mislead you but do refuse to guide you.\n\n- Guiding Gale (detection) A noticeable wind flows continuously toward a destination the spirits think will be valuable for you to find. Though you can't ask for a specific destination, the spirits understand your current circumstances and urgent priorities. They won't lead you to a location you're already aware of or can currently see, unless this might lead you to a fruitful destination you've already dismissed as an option. The spell has a duration of 8 hours or until you reach the destination, whichever comes first. When you arrive, the winds swirl in playful circles and then disperse to make it clear you're in the right place.\n\n- Voice of the Sky (auditory, linguistic, prediction) A voice on the wind, clearly audible to you, gives you advice on a course of action that holds positive potential for you. This advice is rarely more than two or three sentences long, typically spoken in Sussuran if you understand it, and Common if not. If you can't hear, the spirits blow small objects around to mimic written words or sign language. If following the advice poses great danger, the spirits typically note this risk but rarely go into detail. The advice is instant, so the spell doesn't have a duration.","source":{"provider":"PAIZO","sourceId":"4cv1cuBHjYmVfBGI","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wish-twisted-form","name":"Wish-Twisted Form","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus your magic upon an enemy, wishing for their defenses to fail and turning their strengths into weaknesses. The target must attempt one Will saving throw for all of the following effects.\n\n- The target gains weakness 5 to one energy type of your choice.\n\n- The target's resistances are reduced by 5.\n\n- The target takes a –10-foot status penalty to all its Speeds.\n\n- The target takes a -1 status penalty to its saving throws.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes the penalties for 1 round.\n\nFailure The target takes the penalties for 1 minute.\n\nCritical Failure As failure, and the target takes a -1 status penalty to AC for the duration.\n\nHeightened (+1) Increase the weakness and the reduction to resistances by 1.","source":{"provider":"PAIZO","sourceId":"B3tbO85GBpzQ3u8l","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.world-in-shadow","name":"World in Shadow","kind":"RITUAL","rank":5,"rarity":"UNCOMMON","traits":["darkness","mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"TEXT","text":"8-mile radius circle centered on you"},"area":null},"duration":{"text":"5 days","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (mythic), Nature (mythic), or Occultism (mythic), Religion (mythic)","secondaryChecks":"Arcana, Nature, Occultism, Religion (cannot be the same skill as for the primary check)","secondaryCasters":3},"description":"This ritual must be cast at night, at which point darkness becomes everlasting. Casters with darkvision gain a +1 circumstance bonus to their check to cast the ritual.\nCritical Success As success, except that all light levels within the area are lowered by two steps toward darkness, and light effects that would counteract the darkness take a –2 status penalty to their counteract checks.\n\nSuccess All light levels within the area are lowered by one step toward darkness. Areas that are already dark become magical darkness. Light effects that would counteract the darkness only do so in the area of the counteracting spell or effect (for example, 40 feet for a spell).\n\nFailure The ritual has no effect.\n\nCritical Failure The casters are all plunged into their own personal darknesses. For 1 week, each caster can see no farther than 5 feet regardless of ambient light level. Anything beyond that distance is treated as if it were in magical darkness that can't be counteracted; darkvision and greater darkvision similarly can't penetrate this darkness.","source":{"provider":"PAIZO","sourceId":"bODHqeXoEc8GVU6a","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.wronged-monks-wrath","name":"Wronged Monk's Wrath","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","electricity","focus","force","manipulate","monk"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"2d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6","1":"1d12"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You unleash your ki as a powerful storm of force and lightning, dealing 2d6 force damage and 2d12 electricity damage to creatures in the area.\n\nIf you use 2 actions to cast the spell, increase the size of the emanation to 10 feet and the damage to 3d6 force damage and 3d12 electricity damage.\n\nIf you use 3 actions to cast the spell, increase the size of the emanation to 20 feet and the damage to 4d6 force damage and 4d12 electricity damage.\n\nEach creature attempts one basic Reflex save that applies to both types of damage On a failed save, the creature is for 1 round; on a critical failure, the creature also takes 2d12[persistent,electricity] damage and is deafened for 1 minute.\n\nHeightened (+2) The force damage increases by 1d6 and the electricity damage by 1d12, or 2d6 and 2d12 if you use 2 or 3 actions","source":{"provider":"PAIZO","sourceId":"8TBgEzjZxPaOJOm1","book":"Pathfinder #166: Despair on Danger Island","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.wyvern-sting","name":"Wyvern Sting","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","manipulate","poison"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"3d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You duplicate the venomous sting of a wyvern. You deal 3d4 piercing damage to the touched creature and afflict it with wyvern venom. If the target takes piercing damage, they must attempt a Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target takes 5d6[poison] damage.\n\nFailure The target is afflicted with Wyvern Venom at stage 1.\n\nCritical Failure The target is afflicted with wyvern venom at stage 2.\nWyvern Venom (poison) Level 9\n\nMaximum Duration 6 rounds\n\nStage 1 5d6[poison] damage (1 round)\n\nStage 2 6d6[poison] damage (1 round)\n\nStage 3 8d6[poison] damage (1 round)","source":{"provider":"PAIZO","sourceId":"IoHxAkK0uGqrgtWl","book":"Pathfinder #160: Assault on Hunting Lodge Seven","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.youre-mine","name":"You're Mine","kind":"SPELL","rank":5,"rarity":"UNCOMMON","traits":["concentrate","emotion","focus","incapacitation","manipulate","mental","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You manipulate the target's emotions, potentially allowing you to control it for a brief instant. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1.\n\nFailure On the target's next turn, it's Stunned 1 and you partially control it, causing it to take a single action of your choice. If it has actions left, it can act normally.\n\nCritical Failure The target is for 1 round.\n\nHeightened (7th) On a failure, the target is Controlled for 1 round. On a critical failure, the target is Controlled for up to 1 minute; it receives a new Will save at the end of each of its turns, and on a success, the spell ends.","source":{"provider":"PAIZO","sourceId":"x2LALaHXO7644GQA","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.accelerated-decomposition","name":"Accelerated Decomposition","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","oracle","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"fkGxU6Jk2SdLG1OG","formula":"9d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"fkGxU6Jk2SdLG1OG":"1d6"}},"counteraction":false,"ritual":null,"description":"You speed the natural process of a creature's decline and debilitation. As its body withers, the target takes 9d6 void damage and must attempt a Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and is your choice of Clumsy 1, Drained 1, or Enfeebled 1 for 1 round.\n\nFailure The target takes full damage and is clumsy 1, drained 1, and enfeebled 1 for 1 round.\n\nCritical Failure The creature takes double damage and is clumsy 1, drained 1, and enfeebled 1 for 1 minute.\nHeightened (+1) The void damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"rqoWAxQv4RWbwyAr","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ancestral-form","name":"Ancestral Form","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take the form of your ancestral spirits, becoming and quasi-corporeal. You gain resistance 10 to all damage (except force, spirit and damage from Strikes with the property rune), and this resistance is doubled against non-magical and precision damage.\n\nYou gain a fly Speed equal to your land Speed; when Flying, moving upward isn't difficult terrain for you. You can't move through solid objects, but you can float through tiny gaps.\n\nYou can't Cast Spells (but you can Sustain Spells), activate items, or use actions that have the attack or manipulate trait.\nHeightened (+2) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"xEjGEBvTfDJECSki","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.arrow-salvo","name":"Arrow Salvo","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"kIYrspEqRqKoAhHI","formula":"8d10","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"kIYrspEqRqKoAhHI":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You conjure an immense wooden bow that launches a salvo of massive arrows at all nearby enemies. All creatures in the affected area take 8d10 piercing damage, with a basic Reflex save. On a critical failure, the target is knocked from the force of the impact.\n\nHeightened (+1) Increase the damage by 1d10.","source":{"provider":"PAIZO","sourceId":"7PnjDM52lb4LEqHR","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ash-form","name":"Ash Form","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","cursebound","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take the form of a cloud of minuscule ash particles. You gain fast healing 3, resistance 10 to piercing and slashing damage, and immunity to bleed, falling damage, and precision damage. You can't move through solid objects, but you can stream through tiny gaps as if they were difficult terrain. Any ability with the air trait that involves blowing or shifting wind (such as ) deals you 1d6[bludgeoning] damage per rank of the spell each round you are in its area, in addition to its normal effects.\n\nHeightened (9th) The resistance increases to 15","source":{"provider":"PAIZO","sourceId":"2B0C22OuX9YrIJ5y","book":"Pathfinder #185: A Taste of Ashes","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.asmodean-wager","name":"Asmodean Wager","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["linguistic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"parchment, ink, and an item of value from each bettor worth at least 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the wager's completion","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Society","secondaryCasters":0},"description":"You facilitate a magically binding agreement between yourself and one or more additional secondary casters, wherein each participant (hereafter referred to as the bettors) stakes something of value on the outcome of an event that has yet to be determined. The nature of the event is up to the bettors: a test of skill, a game of chance, or even something occurring in the distant future. While named for Asmodeus and invented by those with a diabolical bent, the ritual has no particular connection to Hell and instead relies on the occult connections between the bettors. The stakes can be either of the following:\n\n- A promise or possession. The losers of the bet are placed under the effects of a 9th-rank geas ritual to uphold the promise or turn over a single item they own, as stated at the time of the spell's casting. Once ownership has been transferred or the promise fulfilled, nothing prevents the bettors from trying to reclaim a former possession.\n\n- The bettors' life. As soon as the outcome has been decided, the losers die instantly with no saving throw; this is a death effect. The next time the winner would die, they instead remain alive and at 0 Hit Points with a dying condition 1 lower than would kill them. Until this protection has been exhausted, the loser of the bet can't be returned to life through any means, even powerful magic such as wish. A creature already in possession of an additional life as a result of winning an Asmodean wager can't enter into a new wager with a life as collateral.\n\nIf any participant knowingly and willingly makes any attempt to cheat at or avoid fulfilling the terms of the wager, the spell automatically determines them the loser and resolves accordingly. The spell doesn't function if any participant is acting against their will or being mentally controlled or coerced by any means, or if any participant is immune to or otherwise unaffected by their wager (such as if a construct, undead, or other creature immune to death effects tried to bet its life). At the GM's discretion, if it ever becomes permanently impossible for the bet's outcome to be determined, the spell ends without any further result.\n\nSuccess The ritual is successful.\n\nFailure The ritual has no effect.\n\nCritical Failure The wording of the ritual is imperfect and subverts the bet, causing all bettors to be considered losers regardless of the actual result of the wager.","source":{"provider":"PAIZO","sourceId":"NeyyAPwa639WjYGG","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aura-of-the-unremarkable","name":"Aura of the Unremarkable","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and allies in the area appear to be completely innocuous to other creatures within the spell's area, regardless of the actions you're committing. For example, if you and your allies are loudly interrogating a local for information or aiming a crossbow at a noble from a balcony, creatures who can see you might not think this is unusual. Non-allied creatures in the emanation must attempt a Will save.\n\nCritical Success The creature sees your actions as they really are and announces them as such. All other creatures in the area gain a +1 circumstance bonus to their Will saves to recognize your actions as they really are.\n\nSuccess The creature sees your actions as they really are.\n\nFailure The creature believes your actions are normal and unworthy of concern.\n\nCritical Failure The creature believes you are performing other actions entirely, such as helping a local or waving to a noble, as determined by the GM. The creature doesn't have a chance of remembering events normally.\n\nAny hostile actions by you or your allies against a creature or its allies break the effect of the spell for that creature. So, for example, if an interrogated local's friends or threatened noble's guards saw your actions, they would be unaffected by this spell. When the spell ends (or when affected allies move outside the range of the emanation), observers see things normally but the altered perceptions from earlier events remain in mind. Each mention of the events as noteworthy, such as being questioned about them by an authority figure, grants the target another Will save to break the effect and remember things normally (unless the creature critically failed their save).","source":{"provider":"PAIZO","sourceId":"VUMtDHr8CRwwr3Mj","book":"Pathfinder #166: Despair on Danger Island","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.awaken-animal","name":"Awaken Animal","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"herbs, 1/5 the value on Creature Creation Rituals table"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 animal up to the level on the table","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master)","secondaryChecks":"Lore (any), Society, Survival","secondaryCasters":3},"description":"You grant intelligence to the target, transforming it into a beast. If it was previously an animal companion or minion, it can no longer serve as one.\n\nCritical Success The target's Intelligence, Wisdom, and Charisma modifiers each increase to +2 if they were lower, and it becomes helpful to you for awakening it.\n\nSuccess The target's Intelligence, Wisdom, and Charisma modifiers increase to +0 if they were lower and it becomes friendly to you for awakening it.\n\nFailure You fail to awaken the target.\n\nCritical Failure You accidentally awaken the target with a pure bestial hatred toward you. The target's Intelligence, Wisdom, and Charisma modifiers increase to -2 if they were lower. It becomes hostile to you, attempting to destroy you.\nCreatures Creation Rituals\nCreature LevelSpell Rank RequiredCost\n-1 or 0215 gp\n1260 gp\n23105 gp\n33180 gp\n44300 gp\n54480 gp\n65750 gp\n751,080 gp\n861,500 gp\n962,100 gp\n1073,000 gp\n1174,200 gp\n1286,000 gp\n1389,000 gp\n14913,500 gp\n15919,500 gp\n161030,000 gp\n171045,000 gp","source":{"provider":"PAIZO","sourceId":"B4dDkYsHFo1H0CIF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.awaken-entropy","name":"Awaken Entropy","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"ub9o9w3b7bmmuy9r","formula":"8d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ub9o9w3b7bmmuy9r":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"All things age, all things die, and at the end of days, even the universe will grow quiet and still. You awaken the cosmic principle of entropy, accelerating time in an area—flesh falters, plants shrivel, and even stone begins to crumble. Any creature that enters or begins its turn in the area takes 8d6 void damage with a basic Fortitude save, or 8d6 force damage if the creature normally doesn't take void damage, such as if the creature is a construct or undead. Even beings such as fiends with unlimited lifespans can be worn away by entropy.\n\nThe first time you Sustain the Spell on each subsequent turn, the entropic zone grows stronger in addition to having its duration increased. The radius of the burst increases by 10 feet (to a maximum of 40 feet), and the size of the damage dice increases by one step (from d6 to (2+@item.rank)d8[void|shortLabel], then to (2+@item.rank)d10[void|shortLabel], and finally to (2+@item.rank)d12[void|shortLabel]).\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"ZMvplR106Jxl7B15","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.awaken-object","name":"Awaken Object","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"crushed gems and spices worth 250 gp"},"targeting":{"range":{"kind":"NONE"},"target":"1 non-magical inanimate object","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert) or Occultism (expert)","secondaryChecks":"Crafting, Arcana or Occultism (whichever isn't used for the primary check)","secondaryCasters":2},"description":"You imbue a single Small or smaller object with rudimentary awareness and consciousness, and it gains mental ability modifiers depending on the results of the ritual. It gains the ability to see and hear, and the ability to understand (but not speak) a single language that you know. It's indifferent to you and all living creatures. In all other respects, it's an ordinary object of its type. An awakened object that gains the broken condition is rendered insensate until Repaired above its Broken Threshold.\n\nMagical objects and constructs can't be awakened, nor can most spell or magic item abilities be added to an awakened object later (the process to do so is much more complicated than a ritual and essentially creates an intelligent magic item). However, an object that has already been awakened can have the animate object ritual cast on it by doubling the cost of animate object.\n\nCritical Success The target's Intelligence, Wisdom, and Charisma modifiers each increase to +2 if they were lower, and it becomes friendly to you for awakening it.\n\nSuccess The target's Intelligence, Wisdom, and Charisma modifiers increase to +0.\n\nFailure The target is unaffected and the ritual fails.\n\nCritical Failure The target is unaffected, and the primary caster's intellect is trapped in the object for 24 hours. During this time, their original body is and inert and can't be awakened by any means.","source":{"provider":"PAIZO","sourceId":"9lz67JCNCLDfIEy3","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bacchanalia","name":"Bacchanalia","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["emotion","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"a lavish meal with expensive alcohol for every caster (225 gp)"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until midnight (see text)","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion","secondaryChecks":"Performance","secondaryCasters":8},"description":"You hold an elaborate feast and stoke the celebratory spirit, causing it to spread to other people nearby; you buoy them with hope and good cheer as they revel into the night. The ritual was first developed by the cult of the hero-god Kelksiomides in Iblydos and meant to be a benefit to the community during hard times, though other groups have used it for far different purposes, such as to spread chaos or to provide cover for a heist.\n\nYou and the secondary casters begin your feast in a public space where others can see you, exactly 8 hours before dusk. When dusk falls, you complete the ritual. The party spreads outward from your initial site until it slowly encompasses the settlement (for a town or smaller), or a district or division of up to approximately 1,000 people (for a larger settlement). Those partaking in the celebration are until the ritual comes to an end (or someone uses a hostile action toward them, as usual). The partying appears to spread naturally, as others see the revelers, they too slowly join until the celebration reaches its peak size. The spell's effect ends sharply at midnight, but that doesn't mean people stop partying right away if they're enjoying themselves.\n\nCritical Success The party is a huge hit! The effects work as above, except that in a larger settlement, the celebration can spread to an area with as many as 10,000 people. Furthermore, the celebration leaves strong memories in the hearts of those who participated, causing locals to commemorate it or possibly outlaw such celebrations (depending on their view of the event).\n\nSuccess The party is successful. It spreads as described in the ritual's description.\n\nFailure The party never really catches on. You and the secondary casters get to celebrate, but the most other people do is give you odd looks.\n\nCritical Failure Instead of celebration, you inspire anger and resentment toward you and the secondary casters for disturbing the peace or possibly even deepening the despair of a people who are already troubled. People in the area have their attitudes toward you temporarily adjusted two steps worse than normal. Those who become hostile won't necessarily attack you, but they will mock you, break up your revelry, and potentially arrest you.","source":{"provider":"PAIZO","sourceId":"s0SerOrkkUd7SAH9","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.binding-circle","name":"Binding Circle","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"warding circle ingredients worth a total value of 2 gp × the spell rank × the target's level"},"targeting":{"range":{"kind":"TEXT","text":"interplanar"},"target":"1 extraplanar creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (master) or Occultism (master)","secondaryChecks":"Diplomacy or Intimidation; Arcana or Occultism (whichever isn't used for the primary check)","secondaryCasters":3},"description":"You call forth an extraplanar creature of a level no greater than double that of the binding circle ritual's rank and attempt to bargain with it, generally to perform a task for you in exchange for payment.\n\nYou conjure the extraplanar creature within your circle and negotiate a deal with it. A creature that doesn't wish to negotiate at all can attempt a Will save to stay on its home plane. Most extraplanar creatures feel that they have something better to do than cater to the whims of mortals and require a significant gift, especially if your task poses major risks. Fiends and similarly wicked extraplanar creatures are more likely to accept a bargain for a lower cost as long as it allows them to wreak havoc on the Universe or inflict evil upon the world along the way.\n\nMonetary prices usually range from the cost of a consumable item of the creature's level for a short and simple task to a permanent magic item of the creature's level or more to persuade the creature to fight alongside you. However, some extraplanar creatures may want payments other than money, such as permission to cast a on you to fulfill an unspecified later favor or obtain ownership of your soul via an infernal contract.\n\nYou can add an additional secondary caster to create a warding circle that prevents the extraplanar creature from attacking or leaving the circle during the bargain. This uses the Crafting skill and has the same DC as a secondary check would. This protection ends if you use a hostile action against the extraplanar creature or the warding circle breaks.\n\nCritical Success You call the extraplanar creature and can prevent it from returning home for up to a full day, potentially allowing you to negotiate a better deal by threatening to leave it in the wards for the duration.\n\nSuccess You call the extraplanar creature and must make your case succinctly, after which the creature can return home at any time.\n\nFailure You fail to call the extraplanar creature.\n\nCritical Failure You call something vile and horrible, unbound by your wards, and it immediately attempts to destroy you.","source":{"provider":"PAIZO","sourceId":"2ykmAVKrsAWcazcC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blade-barrier","name":"Blade Barrier","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"7d8","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"Blades of force form a churning wall. The wall is a straight line 20 feet high, 120 feet long, and 2 inches thick, and it provides cover. The wall deals 7d8 force damage to each creature that's in the wall's space when it is created, that attempts to pass through the wall, or that ends its turn inside the wall. A basic Reflex save reduces the damage. A creature that succeeds at this save when the wall is created is pushed to the nearest space on the side of its choice. Creatures trying to move through the wall fail to do so if they critically fail the save, ending their movement adjacent to the wall.\n\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"peCF6VArm8urfwxZ","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blanket-of-stars","name":"Blanket of Stars","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A flowing cloak of utter darkness drapes over you, filled with pinpricks of light like distant stars. It imparts the stillness of the cosmos to you, granting you a +2 status bonus to Stealth checks to and .\n\nWhile outside under a starry night sky, you're also as long as you remain still. When moving under a starry night sky, you're instead.\n\nGazing too closely into the stars is disorienting. Any creature that ends its turn adjacent to you must attempt a Will save; this is a mental, visual effect.\nSuccess The creature is unaffected.\n\nFailure The creature is until the end of its next turn.\n\nCritical Failure The creature is and dazzled until the end of its next turn.","source":{"provider":"PAIZO","sourceId":"m34WOIGZCEg1h76G","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blessed-boundary","name":"Blessed Boundary","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","force","manipulate","sanctified"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":60}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"rQT6Is4xVcbWJIAt","formula":"7d8","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"rQT6Is4xVcbWJIAt":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Manifestations of divine force appear in the hundreds, swirling in a massive, protective sphere. These typically look like spiky fragments, but often take on an appearance themed to the deity of the caster. The sphere is hollow, with the manifestations forming a shell 2 inches deep on the outer edge. You can choose to make the burst smaller, in 5-foot increments, when you cast it. The shell provides cover and can intersect solid terrain without affecting it. The shell deals 7d8 force damage to each creature who intersects with the shell when the sphere's created, or who attempts to move through the shell. The creature also takes the damage at the end of its turn, but only if it didn't already take damage from the shell that turn. The effects are determined by a creature's Reflex save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage, is pushed up to 10 feet in the direction of your choice, and ends its movement.\n\nCritical Failure The creature takes double damage, is pushed up to 20 feet in the direction of your choice, and ends its movement.\n\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"jj5d830iUi2ZlQfs","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blinding-fury","name":"Blinding Fury","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","curse","emotion","incapacitation","mental"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"},"requirements":"A creature damages you"},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"The triggering creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature damages you.\nYou curse the target with your outrage at being attacked. The effect is determined by the target's Will save.\nCritical Success The target is unaffected.\n\nSuccess The target can't Observe you until the end of its turn, and if you're currently observed by it, you become to it.\n\nFailure As success, and for 1 minute, every time the target damages you, it can't observe you until the end of its turn.\n\nCritical Failure As success, and for an unlimited duration, the first time each round the target damages a creature, it can't observe that creature until the end of its turn. If it damages several creatures at once, the creature it can't perceive is chosen randomly among those creatures.","source":{"provider":"PAIZO","sourceId":"NhGXgmI3AjkkwnPk","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.boots-on-the-ground","name":"Boots on the Ground","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["auditory","concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":null},"duration":{"text":"Until you next make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You craft the illusion of your army being much bigger than it actually is, hoping to overwhelm the opposing forces and shatter their hopes. Your illusion can create up to three illusory Gargantuan duplicates of troops within range. You can give the illusion a basic task to perform, such as standing in formation, marching, mimicking guard movements, or unloading illusory boxes; however, the illusion can't perform any actual tasks and can't create intelligible sounds, such as music or clear speech. If you and any of the illusory troops are ever farther than 500 feet apart, the spell ends.\n\nAn illusory troop's AC is equal to your spell DC. Its saving throws modifiers are equal to your spell DC – 10. If an illusory troop is hit by an attack or fails a save, you must attempt a flat. On success, the illusion of that troop is destroyed. On failure, the entire illusion shatters, and all illusory troops are destroyed.\nHeightened (8th) The DC of the is lowered to 8 (flat), and you can create up to five illusory troops.","source":{"provider":"PAIZO","sourceId":"IN46qySRdMdpcd0y","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bound-in-death","name":"Bound in Death","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 enemy","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"You tether another creature's spirit to your own, shunting part of the damage dealt to you onto one of your foes. You create a life link between yourself and the target. Each time an effect damages you, the target attempts a Will save, which can cause it to take part of the damage, as detailed below. The spell ends if the target is ever more than 120 feet away from you. If either you or the target is reduced to 0 Hit Points, any damage from this spell is resolved, and then the spell ends.\n\nEach time you sustain this spell, you can choose to deal 6d8 damage to yourself, which can be reduced with bound in death as normal.\n\nCritical Success The damage you take is unaffected, and the spell ends.\n\nSuccess The damage you take is unaffected, and the target can't take damage from bound in death for 1 round.\n\nFailure The target takes half the damage of the effect instead of you, then can't take damage from bound in death for 1 round. Apply any immunity, resistances, or weaknesses you have to the damage before halving it, and the target still applies any immunity, resistances, weaknesses, and the like it has.\n\nCritical Failure The target takes half the damage of the effect.\n\nHeightened (+2) The damage you can choose to deal to yourself each time you sustain the spell increases by 3d8.","source":{"provider":"PAIZO","sourceId":"B0Ng2VlhEJMuUXUH","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bounty-of-the-sky","name":"Bounty of the Sky","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","healing","manipulate","mythic"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"1Yol9VOB1Bu7G213","formula":"4d6","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"1Yol9VOB1Bu7G213":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You call forth a flock of geese that drop restorative fruits and breads from the sky as they fly overhead. You or an ally in the area can Interact to collect one of these gifts, and can then either consume it as part of the same action or do so with a separate Interact action later in the spell's duration. Enemies who attempt to pick up one of these gifts find that it turns to ash in their hands. Each time a character consumes one of these gifts, they can select one of the following benefits.\n- The character regains 4d6 Hit Points.\n- The character reduces the stage of one poison or disease they suffer from by one stage. This can't reduce the stage below 1 or cure the affliction.\n- The character reduces the value of their , , , or condition by 2, or reduces two of the listed conditions by 1 each.\nHeightened (+2) The amount of Hit Points a character regains from consuming a gift increases by 2d6.","source":{"provider":"PAIZO","sourceId":"txxm6Rj6jNxcFSQ9","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cast-into-time","name":"Cast into Time","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"5d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"5d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"","1":"2d6"}},"counteraction":false,"ritual":null,"description":"You release a wave of temporal energy that sends creatures violently tumbling through time, scarring their thoughts with the information flowing around them. Although the journey can feel like it lasts for minutes or even days, the targets reappear instantly. Witnessing this chaotic flow of time and being bashed against objects from different times deals the targets 5d8 mental damage and 5d6 bludgeoning damage, with a Fortitude save. A creature that falls into time disappears until the end of your turn. It then reappears in the same space it left; if that space is occupied, it appears in the nearest empty space, chosen by the GM.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature falls into time. When it returns, it takes half damage.\n\nFailure The creature falls into time. When it returns, it takes full damage and is Sickened 1.\n\nCritical Failure The creature falls into time. When it returns, it takes double damage and is Sickened 2.\n\nHeightened (+1) The bludgeoning damage increase by 2d6.","source":{"provider":"PAIZO","sourceId":"OdqM06M0wDUqZWiR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.catch-your-name","name":"Catch Your Name","kind":"SPELL","rank":6,"rarity":"RARE","traits":["manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature on your plane speaks your private or true name\n\nRequirements You know your own true name.\n\nYou learn a private name (but not the true name) of the creature who spoke your name, as well as their precise location, unless they succeed at a Will save to negate the effect. You are aware any time the trigger conditions are met as long as you have the spell prepared or in your repertoire. There is no way to distinguish one trigger of this spell from another without actually casting the spell. This can become a nuisance if you are so famous that your name is regularly on others' lips.","source":{"provider":"PAIZO","sourceId":"FyOgUkq71LNC143w","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chain-lightning","name":"Chain Lightning","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","electricity","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"target":"1 creature, plus any number of additional creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"8d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"You discharge a powerful bolt of lightning at the target, dealing 8d12 electricity damage. The target must attempt a basic Reflex save. The electricity arcs to another creature within 30 feet of the first target, jumps to another creature within 30 feet of that target, and so on. You can end the chain at any point. You can't target the same creature more than once, and you must have line of effect to all targets. Roll the damage only once, and apply it to each target (halving or doubling as appropriate for its saving throw outcome). The chain ends if any one of the targets critically succeeds at its save.\n\nHeightened (+1) The damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"TDNlDWbYb58Y55Da","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.champions-sacrifice","name":"Champion's Sacrifice","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["champion","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering ally","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An ally is hit by a Strike, or an ally fails a saving throw against an effect that doesn't affect you.\nYou form a link with an ally, allowing you to take harm in their stead. All the effects of the hit or failed save are applied to you instead of the target. For example, if the target critically fails a saving throw against a fireball, you would take double damage. These effects ignore any resistances, immunities, or other abilities you have that might mitigate them in any way, although those of the target apply before you take the effect","source":{"provider":"PAIZO","sourceId":"USM530HlzZ1RMd99","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chromatic-image","name":"Chromatic Image","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth three illusory images of yourself, and each of the four of you takes on a different color, your colors all shifting each time someone attacks you. This has the effects of , except that whenever a foe destroys one of the images, roll [[/r 1d4]]{1d4} to see which color the image was when it was destroyed. The attacker takes the corresponding effect.\n\n- Red 5[fire] damage and 5[mental] damage.\n\n- Orange 5[acid] damage and 5[mental] damage.\n\n- Yellow 5[electricity] damage and 5[mental] damage.\n\n- Green 5[poison] damage and 5[mental] damage, plus it's Frightened 1.","source":{"provider":"PAIZO","sourceId":"FgRpddPORsRFwNoX","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.claim-undead","name":"Claim Undead","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","incapacitation","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 undead creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attempt to wrest control of a target undead or force it to recognize you as its master. If the target is controlled by another creature, that controller attempts a Will saving throw to retain control; otherwise, the target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1 and for 1 round as it fights off your commands.\n\nFailure The target becomes controlled by you and follows your orders. It (or the creature previously controlling it) can attempt a new Will save at the end of each of its turns; on a success, the spell ends, and the creature becomes stunned 1 and confused for 1 round. If you issue an obviously self-destructive order, the target doesn't act until you issue a new order.\n\nCritical Failure As failure, but the target (or the creature previously controlling it) receives a new save only if you give it a new order that is against its nature.","source":{"provider":"PAIZO","sourceId":"GzN9bG6cKZ96YC6l","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.collective-transposition","name":"Collective Transposition","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"up to 2 creatures","area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You teleport the targets to new positions within the area. The creatures must each be able to fit in their new space, and their positions must be unoccupied, entirely within the area, and in your line of sight. Unwilling creatures can attempt a Will save.\nCritical Success The target can teleport if it wants, but it chooses the destination within range.\n\nSuccess The target is unaffected.\n\nFailure You teleport the target and choose its destination.\nHeightened (+1) The number of targets increases by 1.","source":{"provider":"PAIZO","sourceId":"c3XygMbzrZMgV1y3","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.commune","name":"Commune","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["prediction"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense worth a total value of 150 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (master), Occultism (master) or Religion (master)","secondaryChecks":"Nature, Occultism or Religion (whichever is used for the primary check)","secondaryCasters":1},"description":"You call upon an unknown, powerful being to answer questions. The being varies depending on the skill used for the primary check.\n- Nature Primal spirits of nature, which know about animals, beasts, fey, fungi, plants, topography, and natural resources within a 3-mile radius.\n- Occultism Planar and other mysterious entities such as elementals, forgotten spirits, and monitors, which know about forgotten knowledge, the planes, obscure secrets, and other esoterica.\n- Religion Divine beings like celestials and fiends that know about the gods they serve and the god's respective purview; these are typically a servitor of your deity if you have one.\nYou can ask up to seven questions that could be answered with \"Yes\" or \"No.\" The entity answers with one-word answers such as \"Yes,\" \"No,\" \"Likely,\" and \"Unknown,\" though its answers always reflect its own agenda and could be deceptive.\nCritical Success You contact a more powerful entity aligned strongly with your interests, possibly even your deity. The entity won't attempt to deceive you, though it still might not know the answers. When it's important to provide clarity, the entity will answer your questions with up to five words, such as \"If you leave immediately\" or \"That was true once.\"\n\nSuccess You can ask your questions and receive answers.\n\nFailure You fail to contact an appropriate being.\n\nCritical Failure You are exposed to the enormity of the cosmos and are Stupefied 4 for 1 week (can't remove by any means).","source":{"provider":"PAIZO","sourceId":"7DN13ILADW2N9Z1t","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-skinstitch","name":"Create Skinstitch","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"Rare oils worth 480 gp"},"targeting":{"range":{"kind":"TOUCH"},"target":"1 frame covered in the skin of sentient humanoids","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert)","secondaryChecks":"Crafting","secondaryCasters":1},"description":"You transform the target into a skinstitch, a hideous construct covered in the flesh of sentient humanoids.\n\nCritical Success The target becomes a skinstitch. If it's at least 4 levels lower than you, you can make it a minion which gives it the minion trait. You can have a maximum of four minions under your control. If it doesn't become a minion, you can give it one simple command that it pursues single-mindedly. If you aren't a follower of , it ignores any of your subsequent commands. A follower of Norgorber can give the skinstitch simple commands by presenting a Religious Symbol of the deity and commanding it with a single action that has the auditory and concentrate traits.\n\nSuccess As critical success, except a skinstitch that doesn't become your minion stays in place and attacks anyone that attacks or tries to move it, rather than following your command.\n\nFailure You fail to create the skinstitch.\n\nCritical Failure You create the skinstitch, but it goes berserk and attempts to kill you, ignoring your commands even if you are a follower of Norgorber.","source":{"provider":"PAIZO","sourceId":"NCUXsaj2yFxOVhrK","book":"Pathfinder #158: Sixty Feet Under","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.crimson-breath","name":"Crimson Breath","kind":"SPELL","rank":6,"rarity":"RARE","traits":["manipulate","poison"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"xbLeTUmgQaLSf1Jv","formula":"8d6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You turn a creature toward you and exhale a blast of crimson mist from your mouth, exposing the target to a toxic miasma. The effects are determined by the creature's Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target takes 8d6 poison damage.\n\nFailure The target is afflicted with breath of the mantis god poison at stage 1.\n\nCritical Failure The target is afflicted with breath of the mantis god poison at stage 2.\nBreath of the Mantis God\nSaving Throw fortitude\n\nMaximum Duration 6 minutes\n\nStage 1 3d6 persistent bleed and Drained 1 (1 minute)\n\nStage 2 3d8 persistent bleed and drained 1 (1 minute)\n\nStage 3 3d10 persistent bleed and Drained 2 (1 minute)","source":{"provider":"PAIZO","sourceId":"ExQk8AwDphmckEmZ","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cursed-metamorphosis","name":"Cursed Metamorphosis","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","curse","incapacitation","manipulate","polymorph"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform the target creature into a harmless animal appropriate to the area, with effects based on its Fortitude save.\nCritical Success The target is unaffected.\n\nSuccess The target's body gains minor features of the harmless animal. Its insides churn as they partially transform, causing it to be Sickened 1. When it recovers from the sickened condition, its features revert to normal.\n\nFailure The target transforms for 1 minute but keeps its mind. If it spends all its actions on its turn concentrating on its original form, it can attempt a will save to end the effect immediately.\n\nCritical Failure The target is transformed into the chosen harmless animal, body and mind, for an unlimited duration.","source":{"provider":"PAIZO","sourceId":"dN8QBNuTiaBHCKUe","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.daemon-form","name":"Daemon Form","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph","unholy"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse yourself with the corrupting death and pure malevolence of Abaddon, transforming into a Large daemon battle form. You must have enough space to expand into or the spell is lost. When you cast this spell you choose either lacridaemon, leukodaemon, meladaemon, or venedaemon. The battle form is Medium if you choose lacridaemon or venedaemon. While in this form, you gain the daemon and fiend traits. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 21 + your level. Ignore your armor check's penalty and Speed reduction.\n- 15 temporary Hit Points and weakness 5 to holy.\n- A +2 status bonus to all saving throws against death effects.\n- Resistance 10 to poison.\n- Darkvision.\n- One or more attacks specific to the battle form you use. You're trained with them. Your attack modifier is +21, and you use the listed damage. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead.\n- Athletics modifier of +23, unless your own modifier is higher.\nYou also gain specific abilities based on the type of Daemon you choose:\n- Lacridaemon Speed 25 feet, fly 40 feet resistance 10 to cold\n- Size Medium\n- Melee 1 jaws (magical, unholy), Damage 1d8+12 piercing plus 1d6 cold and 1d4 poison\n- Melee 1 claw (agile, magical, unholy), Damage 1d6+12 slashing plus 1d6 cold.\n\n- Leukodaemon Speed 25 feet, fly 40 feet +2 status bonus to saves against diseases\n- Size Large\n- Melee 1 jaws (magical, reach 10 feet, unholy), Damage 2d10+12 piercing\n- Melee 1 claw (agile, magical, reach 10 feet, unholy), Damage 2d6+12 slashing;\n- Ranged 1 composite longbow (deadly 1d10, magical, propulsive, range increment 100 feet, unholy, volley), Damage 2d8+12 piercing.\n\n- Meladaemon Speed 25 feet, fly 40 feet\n- Size Large\n- Melee 1 jaws (magical, reach 10 feet, unholy), Damage 2d10+12 piercing\n- Melee 1 claw (agile, magical, reach 10 feet, unholy, void), Damage 1d6+12 slashing plus 1d6 void, and you can spend an action after a hit to attempt to Grab the target.\n\n- Venedaemon Speed 25 feet sense magical items and active spells within 60 feet as an imprecise sense\n- Size Medium\n- Melee 1 tentacle (agile, magical, reach 10 feet, unholy), Damage 2d6+12 bludgeoning.","source":{"provider":"PAIZO","sourceId":"aSDfGcUOUVGU5m1g","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.demon-form","name":"Demon Form","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph","unholy"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You corrupt yourself with the sin of the Outer Rifts, transforming into a Medium demon battle form. When you cast this spell, choose abrikandilu, brimorak, kithangian, or vloriak. If you choose kithangian, the battle form is Large and you must have enough space to expand into or the spell is lost. While in this form, you gain the demon and fiend traits. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 20 + your level. Ignore your armor check's penalty and Speed reduction.\n- 30 temporary Hit Points, weakness 5 to cold iron, and weakness 5 to holy.\n- Darkvision.\n- One or more attacks specific to the battle form you use. You're trained with them. Your attack modifier is +22, and you use the listed damage. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your attack modifier is higher for the given unarmed attack or weapon, you can use it instead.\n- Athletics modifier of +23, unless your own modifier is higher.\nYou also gain specific abilities based on the type of demon you choose:\n- Abrikandilu Speed 25 feet;\n- Melee 1 jaws (magical, unholy), Damage 2d6+12 piercing, and clumsy 1 for 1 minute on a critical hit;\n- Melee 1 claw (agile, magic, unholy), Damage 2d6+12 slashing;\n- Ranged1 hurled debris (range increment 20 feet, unholy), Damage 2d6+6 bludgeoning.\n\n- Brimorak Speed 30 feet;\n- Melee 1 flaming sword (magical, unholy), Damage 2d8+10 slashing plus 1d6 fire;\n- Melee 1 hoof (agile, unholy), Damage 2d4+10 bludgeoning plus 1d6 fire.\n\n- Kithangian Speed 30 feet;\n- Melee 1 pincer (magical, reach 10 feet, unholy), Damage 1d12+12 slashing, and you can spend an action after a hit to attempt to Grab the target\n- Melee 1 stinger (agile, magical, reach 10 feet, unholy), Damage 1d8+12 piercing; all melee Strikes deal 2d6 additional precision damage to animals.\n\n- Vloriak Speed 25 feet; resistance 10 to acid;\n- Melee 1 claw (unholy), Damage 2d6+12 piercing plus 1d6 spirit;\n- Melee 1 tongue (agile, reach 10 feet, unholy), Damage 1d6+12 acid plus 1d6 spirit.","source":{"provider":"PAIZO","sourceId":"dKbv80rlAWVpz83C","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.devil-form","name":"Devil Form","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph","unholy"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bind yourself to the power of Hell, transforming into a Medium devil battle form. When you cast this spell, choosecoarti, levaloch, sarglagon, or vordine. If you choose levaloch or sarglagon, the battle form is Large and you must have enough space to expand into or the spell is lost. While in this form you gain the devil and fiend traits. You have hands in this battle form and can use manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of the form that you choose:\n- AC = 22 + your level. Ignore your armor check's penalty and Speed reduction.\n- 5 temporary Hit Points, resistance 5 to physical damage (except silver), and weakness 5 to holy.\n- Resistance 10 to fire.\n- Darkvision.\n- One or more attacks specific to the battle form you use. You're trained with them. Your attack modifier is +20, and you use the listed damage. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your attack modifier is higher for the given unarmed attack or weapon, you can use it instead.\n- Athletics modifier of +23, unless your own modifier is higher.\nYou also gain specific abilities based on the type of devil you choose:\n- Coarti Speed 25 feet, fly 40 feet;\n- Size Medium\n- Melee 1 morningstar (magical, unholy, versatile P), Damage 2d6+12 bludgeoning plus 1d6 spirit;\n- Melee 1 wing (agile, unholy, versatile P), Damage 1d6+12 bludgeoning plus 1d6 fire.\n\n- Levaloch Speed 30 feet, climb 30 feet; +2 circumstance bonus to Fortitude DC against being Shoved and to other saving throws to resist being moved against your will;\n- Size Large\n- Melee 1 trident (magical, unholy) Damage 2d8+10 piercing;\n- Ranged 1 trident (magical, thrown 20 feet, unholy), Damage 2d8+10 piercing; all melee Strikes deal 2d6 additional precision damage to clumsy, enfeebled, immobilized, or restrained creatures.\n\n- Sarglagon Speed 25 feet, fly 25 feet, swim 30 feet;\n- Size Large\n- Melee 1 fangs (magical, unholy), Damage 2d10+10 piercing;\n- Melee 1 tentacle arm (agile, magical, unholy), Damage 1d8+10 bludgeoning plus 1d6 poison.\n\n- Vordine Speed 25 feet;\n- Size Medium\n- Melee 1 trident (magical, unholy) Damage 2d8+12 piercing;\n- Melee 1 hoof (agile, magical, unholy), Damage 1d4+12 plus 1d6 fire;\n- Melee 1 whip (disarm, magical, nonlethal, reach 10 feet, trip, unholy), Damage 2d4+10 slashing;\n- Ranged 1 trident (magical, thrown 20 feet, unholy), Damage 2d8+12 piercing.","source":{"provider":"PAIZO","sourceId":"dR53f0p15EW7D0xC","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.disintegrate","name":"Disintegrate","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["attack","concentrate","manipulate"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature, unattended object, or force construct","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"12d10","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d10"}},"counteraction":false,"ritual":null,"description":"A black tracer bolt flies toward your target, and upon making contact intensifies into a powerful destructive beam. Make a spell attack against the target. If you hit an object or force construct (such as a wall of force), it's destroyed with no save unless it's an artifact or similarly powerful. A single casting can destroy no more than a 10-foot cube of matter. If you hit a creature, it takes 12d10 damage (no damage type) with a basic Fortitude save. If you critically hit, the target gets a result one degree of success worse than the outcome of its Fortitude save. A creature reduced to 0 HP is blasted to fine powder; its gear remains.\n\nHeightened (+1) The damage increases by 2d10.","source":{"provider":"PAIZO","sourceId":"r7ihOgKv19eJQnik","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dominate","name":"Dominate","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take command of the target, forcing it to obey your orders. If you issue an obviously self-destructive order, the target doesn't act until you issue a new order. The effect depends on its Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Stunned 1 as it fights off your commands.\n\nFailure You control the target. It gains the condition, but it can attempt a Will save at the end of each of its turns. On a success, the spell ends.\n\nCritical Failure As a failure, but the target receives a new save only if you give it a new order that is against its nature, such as killing its allies.\n\nHeightened (10th) The duration is unlimited.","source":{"provider":"PAIZO","sourceId":"OsOhx3TGIZ7AhD0P","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dragon-form","name":"Dragon Form","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Calling upon powerful magic, you gain a Large dragon battle form. When you Cast this Spell, choose one type of common dragon or another type to which your GM allows access. While in this form, you gain the dragon trait. You have hands in this battle form and can take manipulate actions. You can Dismiss the spell.\n\nYou gain the following statistics and abilities regardless of which battle form you choose:\n- AC = 18 + your level. Ignore your armor's check penalty and Speed reduction.\n\n- 10 temporary Hit Points.\n\n- Speed 40 feet, fly 100 feet. You gain any of the following Speeds the chosen dragon has, but with the listed amount: burrow 20 feet, climb 40 feet, swim 60 feet.\n\n- Resistance 10 against the damage type of your Dragon Breath (see below).\n\n- Darkvision and imprecise scent 60 feet.\n\n- The following unarmed melee attacks, which are the only attacks you can Strike with. You're trained with them. Your attack modifier is +22, and your damage bonus is +6. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead. See below for more on these attacks.\n- Melee 1 jaws, Damage 2d12 piercing plus 2d6 damage of the same damage type as your Dragon Breath (see below);\n\n- Melee 1 claw (agile), Damage 3d10 slashing;\n\n- Melee 1 tail (reach 10 feet), Damage 3d10 bludgeoning.\n\n- Athletics modifier of +23, unless your own is higher.\n\n- Dragon Breath 2 You exhale deadly magical energy in an area, dealing 10d6 damage to each creature in the area with a basic save against your spell DC. The shape, damage type, and save type match that of your chosen dragon's breath. If the chosen dragon's breath can deal more than one type of damage, choose one when you cast dragon form. The shape is a 30-foot cone or a 100-foot line. Once activated, Dragon Breath can't be used again for 1d4 rounds. Dragon Breath has the tradition trait matching the type of dragon and the damage trait matching the type of damage it deals, if applicable.\n\n- Tradition Resistance If the dragon's magical tradition matches that of your dragon form spell, you gain the listed ability. Arcane resistance 5 against magic; divine resistance 10 to spirit, vitality, and void; occult resistance 10 to mental; primal resistance 5 to physical damage.\n\nDragonTraditionSpeedsDragon BreathSaving Throw\nAdamantinePrimalBurrowCone of bludgeoningReflex\nBarrageArcane—Cone of forceReflex\nBogPrimalSwimCone of acidReflex\nBrinePrimalSwimLine of bludgeoningReflex\nCinderPrimal—Cone of fireReflex\nCloudPrimal—Cone of electricityReflex\nConspiratorOccultClimbCone of poisonFortitude\nCoralPrimalSwimLine of bludgeoningReflex\nCrystalPrimal—Cone of piercingReflex\nDelightDivine—Cone of spiritReflex\nDespairOccult—Cone of sonicWill\nDiabolicDivine—Cone of fireReflex\nEmpyrealDivine—Cone of spiritReflex\nExecutorDivine—Cone of sonicReflex\nForestPrimal—Cone of piercingReflex\nFortuneArcane—Cone of forceReflex\nHornedPrimalSwimCone of poisonFortitude\nMagmaPrimalBurrowCone of fireReflex\nMirageArcaneClimbCone of mentalWill\nMockingOccult—Cone of bludgeoningReflex\nOathDivine—Cone of spiritWill\nOmenOccult—Cone of mentalWill\nPhaseArcane—Cone of forceReflex\nRequiemDivineSwimLine of spiritWill\nResurrectionDivine—Cone of voidFortitude\nRimePrimalSwimCone of coldReflex\nRuneArcane—Cone of fireReflex\nSageOccult—Cone of mentalWill\nSeaArcaneSwimCone of bludgeoningReflex\nSkyDivine—Cone of electricityReflex\nSovereignOccult—Cone of mentalWill\nStormcrownPrimal—Line of electricityReflex\nTimeArcane—Cone of forceWill\nUmbralOccult—Cone of voidReflex\nUnderworldArcaneBurrowCone of fireReflex\nVizierOccultSwimCone of fireReflex\nVorpalArcane—Cone of voidWill\nWailingArcane—Cone of sonicFortitude\nWhisperOccult—Cone of mentalWill\nWishArcaneClimbCone of mentalWill\nHeightened (8th) Your battle form is Huge, you gain a +20-foot status bonus to your fly Speed, and your attacks have 10-foot reach (or 15-foot reach if they previously had 10-foot reach). You instead gain AC = 21 + your level, 15 temporary HP, an attack modifier of +28, a damage bonus of +12, and Athletics +28. Your Dragon Breath deals an additional 4d6 damage.","source":{"provider":"PAIZO","sourceId":"5c692cCcTDXjSEzk","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dread-secret","name":"Dread Secret","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","emotion","fear","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"up to 6 creatures","area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You utter a powerful secret at odds with the fundamental nature of the target creatures. Choose a specific resistance or weakness with a numerical value that you believe one or more of the targets have due to or previous experience with the targets, such as resistance to fire or weakness to silver. If the information is incorrect for a given target, the spell has no effect on that target. Affected targets must attempt a Will saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 1 damage that matches the type or trait of weakness you chose (thus triggering the creature's weakness) if you chose a weakness, or loses its resistance until the end of your next turn if you chose a resistance.\n\nFailure As success, and the creature becomes Frightened 1 from the revelation of its dread secret.\n\nCritical Failure As failure, except the creature is Frightened 3","source":{"provider":"PAIZO","sourceId":"XULNb8ItUsfupxqH","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.earth-and-sky","name":"Earth and Sky","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["air","concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You erupt into the air with the force of a dragon taking flight, launching nearby creatures into the sky with you. This spell has no effect unless you're on solid ground when you cast it. You fly directly upward, up to 100 feet into the air. When the spell ends, you safely float to the ground, as gentle landing. Every other creature in the area when you Cast this Spell must attempt a Fortitude saving throw.\nCritical Success The creature is unaffected.\n\nSuccess The creature is launched the same distance into the air as you, then falls.\n\nFailure The creature is launched the same distance into the air as you, then falls and can't Arrest its Fall.\n\nCritical Failure As failure, but the creature takes twice as much damage from falling.","source":{"provider":"PAIZO","sourceId":"XOs8C2eZJAO3go0N","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-confluence","name":"Elemental Confluence","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["air","concentrate","earth","fire","manipulate","metal","water","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure four types of elementals who combine forces to form into a chaotic storm. The confluence has AC 28 and 120 Hit Points, weakness 10 to area effects, and immunity to bleed and poison. Creatures can move through the confluence; creatures within the confluence are concealed, and all creatures outside the confluence are concealed to creatures within it. When you Cast or Sustain this Spell, you choose up to two different types of elementals to act.\n\n- Air (air, electricity) The elemental looses a bolt of electricity from the confluence, dealing 4d4[electricity] damage to creatures within 20 feet of the confluence, with a basic Reflex save. This doesn't affect creatures that are completely inside of the confluence.\n\n- Earth (earth) The confluence gains a +2 circumstance bonus to AC and resistance 10 to all physical damage (except adamantine) for 1 round.\n\n- Fire (fire) Flames roar through the confluence, dealing 1d6[persistent,fire] damage to those partially or entirely inside the confluence.\n\n- Metal (metal) The elemental flings shards of metal through the confluence, dealing 2d6[slashing] damage to those partially or entirely inside the confluence with a basic Reflex save. A creature that critically fails also takes 1d6[persistent,bleed] damage.\n\n- Water (attack, water) The elemental expels a powerful jet of water. Attempt a ranged spell attack against a target within 60 feet of the confluence, using your spell attack roll modifier. This attack ignores concealment granted by the confluence, and the elemental gets a +2 circumstance bonus on the spell attack roll against a target inside the confluence. The water deals 4d6[bludgeoning] damage on a hit (doubled on a critical hit). This attack doesn't count toward your multiple attack penalty.\n\n- Wood (wood) Roots and stumps grow, making ground in the area difficult terrain.","source":{"provider":"PAIZO","sourceId":"Cpj05laa7ogqGwS3","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entreat-the-many","name":"Entreat the Many","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"44Rog4IqtGnk82au","formula":"8d8","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"44Rog4IqtGnk82au":"1d8"}},"counteraction":false,"ritual":null,"description":"You manifest echoes of all the spirits you've ever bonded with at once, in a spiraling cyclone of colorful forms. They deal 8d8 force damage to each enemy in the area, with a basic Fortitude save. Additionally, creatures that critically fail the save are knocked .\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"Vg4K3dTDswNQf4Bx","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.explosive-barrage","name":"Explosive Barrage","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","fire","manipulate","sonic"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"Kyiil5NPyBNv1RmH","formula":"6d8","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"vm1Pfy962Ypzup69","formula":"6d4","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Kyiil5NPyBNv1RmH":"1d8","vm1Pfy962Ypzup69":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Area (continued) 20-foot burst plus additional {5-foot bursts}\nYou fire a booming, fiery explosion followed by a salvo of smaller blasts, each cracking the air with the sound of thunder. You create a 20-foot burst and [[/r 1d4#Additional 5-foot bursts]] additional 5-foot bursts each within the range and within 20 feet of another burst. None of the bursts can intersect. Each creature caught in at least one of these bursts takes 6d8 fire damage and 6d4 sonic damage (basic Fortitude save). On a failed save, a creature is also for 1 minute.\nHeightened (+1) The fire damage increases by 1d8 and the sonic damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"ZvB9sV7NLdpDeoTw","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.fateful-condemnation","name":"Fateful Condemnation","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["aura","concentrate","incapacitation","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"MTNvoqutBnRQtZMa","formula":"8d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You draw upon the target's negative fate, causing this lingering destiny to afflict it and its nearby allies with the unintended consequences of its past lives. Spiritual echoes of the target's past lives instill overwhelming feelings of doubt, regret, and despair into the minds of the target and its nearby allies. The effects depend on the target's Will save, with the following results.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes 4d6 mental damage, and then an aura of shimmering mist with a surrounds the creature. This mist isn't dense enough to affect sight, but it does cause the creature and any of its allies in the aura to take a –1 status penalty to all skill checks.\n\nFailure As success, but the creature takes an initial 8d6 mental damage and is then Slowed 1 for the duration of the effect.\n\nCritical Failure As success, but the creature takes an initial 16d6 mental damage, then is slowed 1 for the duration of the effect. Any of the target's allies who begin their turn in the is slowed 1 for 1 round.","source":{"provider":"PAIZO","sourceId":"ReUoodsqUYSTwSgE","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.field-of-life","name":"Field of Life","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A field of life energy fills the area, exuding warmth and rejuvenating those within. Each living creature that starts its turn in the area regains 1d8 Hit Points, and any undead creature that starts its turn in the area takes 1d8 vitality damage.\n\nHeightened (8th) The healing and damage increase to 1d10.\n\nHeightened (9th) The healing and damage increase to 1d12.","source":{"provider":"PAIZO","sourceId":"x5rGOmhDRDVQPrnW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.field-of-razors","name":"Field of Razors","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"fiGNEgajuvkIMj7d","formula":"5","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"fiGNEgajuvkIMj7d":"2"}},"counteraction":false,"ritual":null,"description":"You grind a chunk of your choice of metal to fine dust between your hands and blow it into the air, where it grows into a tangle of wires covered in razor-sharp prongs. The metal must be of a type you currently have in your possession. The covered area is difficult terrain. A creature that moves through the area takes 5[slashing] damage per square traversed.\n\nIf a creature takes slashing, piercing, or persistent bleed damage while inside the thicket, you can spend a reaction to grow the iron in the shed blood into additional wires, expanding the burst by 5 feet. You can grow the area four times in this way, to a maximum of a .\n\nThe barbed wires are made of the metal you chose and activate resistances, weaknesses, and the like normally. The metal reforms in your possession when the spell ends.\n\nHeightened (+1) The damage per square increases by 2.","source":{"provider":"PAIZO","sourceId":"MLYTWHfewOpI3Cz7","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fire-seeds","name":"Fire Seeds","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","fire","manipulate","plant"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Four acorns grow in your hand, their shells streaked with pulsing red and orange patterns. You or anyone else who has one of the acorns can toss it up to 30 feet with an Interact action. It explodes in a 5-foot burst, dealing 4d6 fire damage. The save uses your spell DC, even if someone else throws the acorn. Flames continue to burn on the ground in the burst for 1 minute, dealing 2d6[fire] damage to any creature that enters the flames or ends its turn within them. A creature can take damage from the continuing flames only once per round, even if it's in overlapping areas of fire created by different acorns. When the spell ends, any remaining acorns rot and turn to ordinary soil.\n\nHeightened (8th) The burst's damage increases to 5d6, and the continuing flames damage increases to 3d6[fire] damage.\n\nHeightened (9th) The burst's damage increases to 6d6, and the continuing flames damage increases to 3d6.","source":{"provider":"PAIZO","sourceId":"kuoYff1csM5eAcAP","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.flame-vortex","name":"Flame Vortex","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["air","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"CYLINDER","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d4","1":"1d6"}},"counteraction":false,"ritual":null,"description":"Area 5-foot radius, 40-foot tall cylinder\n\nYou combine a blazing inferno and air currents into a fiery vortex. You can Cast this Spell only if you are outside or the ceiling is 40 feet or higher. All squares in the vortex are difficult terrain for flying creatures.\n\nAll creatures in the area take 3d4 bludgeoning damage and 3d6 fire damage as gusts of fiery wind buffet them, with a basic Reflex save. Each time you Sustain the Spell, you can move the whirlwind up to 20 feet in a straight line. Each creature the whirlwind moves through takes the damage with a basic Reflex save. A creature can take damage from a flame vortex only once per round.\n\nHeightened (+2) The vortex deals an additional 1d4 bludgeoning damage and 1d6 fire damage.","source":{"provider":"PAIZO","sourceId":"Gn5deIoobHpd3SiR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.flaming-fusillade","name":"Flaming Fusillade","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call upon an endless barrage of flames, a series of explosions bursting around you like miniature suns. You cast as part of casting flaming fusillade. For the duration of flaming fusillade, ignition's casting time is reduced from 2 actions to 1.\nHeightened (9th) For the duration, you also gain a status bonus to damage dealt by ignition equal to flaming fusillade's spell rank.","source":{"provider":"PAIZO","sourceId":"bynT1UKaDqr8dLNM","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.for-love-for-lightning","name":"For Love, For Lightning","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","electricity","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3},"requirements":"You are wielding a sword or spear made partly or wholly of metal."},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"vs7xcxeuyzp4tjda","formula":"3d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"vs7xcxeuyzp4tjda":"1d12"}},"counteraction":false,"ritual":null,"description":"When you Cast the Spell, you plunge the required weapon into the ground, where it crackles with crimson lightning. When you Cast the Spell, and the first time during each of your subsequent turns that you Sustain the spell, the crimson lightning arcs. When the weapon arcs, one enemy of your choice within 30 feet of the weapon takes 3d12 electricity damage (basic Reflex save). If you Interact to draw the weapon from the ground, the spell ends.\n\nHeightened (+2) The damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"mtxMpGWpwwWSbySj","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.form-of-the-sandpoint-devil","name":"Form of the Sandpoint Devil","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["evil","polymorph"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"igneous stones and gems worth 1,500 gp, bat wings, horse hooves, and at least one lizard"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 days","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (master)","secondaryChecks":"Arcana, Occultism, Religion","secondaryCasters":4},"description":"You infuse yourself with incredible amounts of pure evil, subsuming your consciousness into malevolence and giving yourself a monstrous form resembling that of the Sandpoint Devil.\n\nBeginning at dawn, you and your accomplices lay out a fire directly on loose earth, layering the igneous rocks and gems into the fire pit. When the fire is hot enough, you roast bat wings, horse hooves, and lizards over it until they're tender enough to eat; for the hooves, this could take hours. Throughout this time, you meditate and recite passages of texts holy to Lamashtu, ruminating on the beauty and necessity of the monstrous and twisting your mindset into a monstrous shape, the better to hold the evil that will come to possess you.\n\nOnce the wings, hooves, and lizards are cooked, you and your accomplices eat these items in their entirety, tearing them only with your teeth, and you must eat more than anyone else involved. You then scoop out a trench at the location where you previously lit the fire, folding the hot rocks into the earth. Your accomplices then bury you shallowly in the trench-you should be able to breathe but not necessarily able to see. Your accomplices then recite the correct texts and draw upon the power of transmutation while you infuse your mind further with the power and beauty of the monstrous. This stage continues for hours, until the setting of the sun. With the departure of its final ray and in accordance with your faith and occult power, you'll rise transformed.\n\nCritical Success You sprout enormous bat wings, a lizard-like tail, pointed teeth, hooves, and an equine head. You gain darkvision; if you already had darkvision, you instead gain greater darkvision. You gain jaws and hoof unarmed melee Strikes, which are the only attacks you can use. You're trained with them. Your attack modifier is +23 or your unarmed attack modifier, whichever is higher. Your jaws Strike deals (2d10+6)[piercing] damage, and your hoof Strike deals (2d6+6)[bludgeoning] damage with the agile and versatile S traits. These attacks are Strength-based (for the purpose of the enfeebled condition, for example). You gain a fly Speed of 40 feet. You also gain a version of the Sandpoint Devil's Accursed Breath: once per hour, you can breathe a of flame that deals 10d6[fire] damage. Your mind transforms, subsuming your own personality with that of the Sandpoint Devil. Unlike many polymorph spells, you can't Dismiss this spell.\n\nSuccess As critical success, except your fly Speed is 20 feet, and you can use your breath weapon once per day.\n\nFailure You fail to transform yourself.\n\nCritical Failure Not only do you fail to transform yourself, but the ritual's secondary casters all transform into Sandpoint Devils for 1 minute, and they immediately attack you.","source":{"provider":"PAIZO","sourceId":"FKtPRWcs4zhwn9N1","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.frost-pillar","name":"Frost Pillar","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["cold","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Ice crystallizes around a creature, imprisoning it within an icy pillar. On a successful saving throw, the creature is pushed to an adjacent space of its choice; otherwise, it's frozen inside the pillar and becomes as its body can barely move within the ice. The ice has AC 10, Hardness 10, and 60 Hit Points; it's immune to critical hits, cold damage, and precision damage, and it has weakness 15 to fire. If the ice is destroyed, the creature within is freed and the spell immediately ends.","source":{"provider":"PAIZO","sourceId":"R5r4vtmlvOA8hDiF","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.frozen-fog","name":"Frozen Fog","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"tXeGnIO0I1i73fxa","formula":"6d8","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"tXeGnIO0I1i73fxa":"3d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You conjure a chilling mist that settles into the bones and makes it difficult to move. This has the effects of , except that you can Sustain the spell once per round to move the fog up to 10 feet. A creature that starts its turn in the area takes 6d8 cold damage with a basic Fortitude save. A creature that fails its save is also Clumsy 1 for 1 minute (Clumsy 2 on a critical failure) and takes a –10-foot status penalty to Speeds for as long as it's clumsy.\n\nHeightened (+2) The damage increases by 3d8.","source":{"provider":"PAIZO","sourceId":"nOVSmPZsCm1C1sI3","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.gray-shadow","name":"Gray Shadow","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","manipulate","shadow"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 dying creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You pray over a dying creature, drawing its shadow into your service as long as its owner is stooped at death's door.\n\nYou summon a in a space adjacent to the dying creature. The greater shadow has its usual stats, with the following modifications:\n- The greater shadow's shadow hand Strike deals an additional 1d8 poison damage.\n- When you Cast a Spell, you can use the greater shadow's location as the origin point instead of your own location. Upon doing so, the greater shadow immediately disappears.\nIf the dying creature targeted by this spell dies or regains consciousness, the greater shadow disappears and this spell ends.","source":{"provider":"PAIZO","sourceId":"rTvNWcKNpOnGklGF","book":"Pathfinder #171: Hurricane's Howl","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.hags-fruit","name":"Hag's Fruit","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","curse","incapacitation","manipulate","sleep"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 non-magical fruit","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You imbue a single piece of fruit with a curse that leaves its victims in a magical sleep. The first person to eat the fruit within the spell's duration is subject to the Curse of Slumber, using your spell DC as the saving throw DC of the curse.\n\nCurse of Slumber (curse, incapacitation, necromancy, sleep)\n\nLevel 11\n\nEffect You fall asleep for 1 round (or permanently on a critical failure) and seem to be dead; a creature must succeed at a medicine check to realize you're alive. Noise doesn't awaken you, but taking damage gives you a new saving throw against the curse.","source":{"provider":"PAIZO","sourceId":"3KiM09e8DN9AdTPA","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.halcyon-infusion","name":"Halcyon Infusion","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"target":"one willing creature of lower level than you","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse magical energy into your target, opening up their mind to the pathways of magic and granting them the ability to use magic to affect the world around them.\n\nChoose a 1st-rank spell you prepared today or that's in your repertoire, of the same tradition you used to cast halcyon infusion. The spell must be one that has a listed range. If the target is at least 3rd level, you can choose a 2nd-rank spell instead of a 1st-rank spell; and if the target is at least 5th level, you can choose a 3rd-rank spell. The target can Cast the Spell once per day as an innate spell of the tradition you used to cast halcyon infusion. If they are untrained in the appropriate magical tradition, their spell attack bonus is 2 + their level + their highest mental ability modifier, and their spell DC is 12 + their level + their highest mental ability modifier.\n\nUnlike most abilities that can only be used once per day, the target refreshes their use of the granted innate spell each day only after you make your daily preparations and choose to extend halcyon infusion's duration by either refraining from preparing a spell in the slot (if you're a prepared spellcaster) or expending another spell slot (if you're a spontaneous spellcaster).\n\nHeightened (8th) If the target is at least 7th level, you can choose a 4th-rank spell.\n\nHeightened (10th) As 8th, and if the target is at least 9th level, you can choose a 5th-rank spell.","source":{"provider":"PAIZO","sourceId":"UJmKPm1FC6pf6txP","book":"Pathfinder Lost Omens Legends","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heinous-future","name":"Heinous Future","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["curse","incapacitation","manipulate","mental","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You hold up a fractured mirror to the target, and in that mirror it sees a thing that may yet come to pass—a ghastly foretelling that the target instinctively knows is eerily possible. It's not a guaranteed thing, just a dreadful possibility, but it haunts the target's thoughts all the same.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Slowed 1 and Stupefied 1 for 1 round.\n\nFailure The target is slowed 1 and stupefied 1 until it next gets eight hours of rest.\n\nCritical Failure The target is Slowed 2 and Stupefied 2, decreasing these conditions by 1 for each eight hours of rest it gets.","source":{"provider":"PAIZO","sourceId":"EX6gTy8s4wNyhOnl","book":"Pathfinder Wake the Dead #3","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.heroic-feat","name":"Heroic Feat","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","cursebound","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain the ability to perform a specialized combat technique from the vast wealth of martial knowledge your mystery provides.\n\nWhen you Cast this Spell, you use the action granted by one common fighter feat. If you Cast this Spell using 2 actions, the granted action must be a single action, and if you Cast this Spell using 3 actions, you can instead choose a feat that grants a 2-action activity.\n\nThe chosen feat's level can be no higher than heroic feat's spell rank. The feat can't have a Frequency entry, and you must meet its prerequisites and requirements in order to select it.","source":{"provider":"PAIZO","sourceId":"4j0FQ1mkidBAXuQV","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ideal-mimicry","name":"Ideal Mimicry","kind":"RITUAL","rank":6,"rarity":"UNCOMMON","traits":["mental"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"6 days"},"cost":"crafting materials worth at least 50 gp × the target's level; a lock of hair from the target, nail clippings from the target, or a vial of blood from the target"},"targeting":{"range":{"kind":"TEXT","text":"see text"},"target":"1 sentient living creature","area":null},"duration":{"text":"until used 10 times or until the target's body parts are removed from the doll","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"3d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Crafting","secondaryCasters":1},"description":"You craft a doll with care and quiet meditation on the target, inserting the fingernails into the body, tying the lock of hair around the neck of the doll, or emptying the vial of blood into the stuffing and allowing it to be absorbed. You then stuff the doll and form it to mimic the shape of the target, creating clothing and accessories for the doll that are similar to commonly worn items. You must have been within 5 feet of the target at least once and gotten a good look at them to perform this ritual. You can cast the ritual and create the doll at any range from the target.\n\nOnce the doll is complete, you can Interact with the doll violently once per round to cause pain to the target as long as they're within 200 feet. This pain manifests as mental damage inflicted on the target, and it depends on how many of the three body part components (hair, nails, or blood) you included in the creation of the doll. After the first time you manipulate the doll, you can continue to do so until either the target moves beyond 200 feet or until you Interact with the doll to cause pain 10 times, whichever comes first. After either of those conditions is met, the doll falls apart into stuffing and dust.\n\nCritical Success The doll becomes connected to the target. Each Interact action causes 3d6 mental damage to the target for each of the three body part components (maximum 9d6 for all three components). The connection is more powerful than normal, increasing the number of times you can Interact to cause pain from 10 to 20.\n\nSuccess As critical success, except you can only Interact the normal 10 times.\n\nFailure The doll is just an ordinary doll.\n\nCritical Failure Any Interact actions you take to cause pain to target instead cause 9d6 damage to the casters. The target is alerted to the attempt nonetheless, through a feeling of the connection being subverted.\n\nHeightened (+2) Increase the damage to the target by 1d6 per body part component, and the damage to the casters on a critical failure by 3d6.","source":{"provider":"PAIZO","sourceId":"M6HsK7W6JMkJXeog","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["RANGE_NOT_STRUCTURED"]}},{"id":"pf2e.spell.kaiju-ward","name":"Kaiju Ward","kind":"RITUAL","rank":6,"rarity":"RARE","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 physical structure","area":null},"duration":{"text":"14 days","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Crafting (mythic)","secondaryChecks":"Engineering Lore, Kaiju Lore, Survival, Warfare Lore","secondaryCasters":4},"description":"You protect a physical structure from the devastation caused by immense creatures. This structure can be artificially constructed, like a castle or wall, or a natural subject, like a specific tree or grove. A given casting of this ritual can protect a subject as small as a single-story house and no larger than the wall surrounding a large city.\nCritical Success As success, but the target structure also doubles its Hit Points and Broken Threshold.\n\nSuccess The target structure gains a +4 status bonus to AC and its Hardness increases by 10. It also gains resistance 20 to acid, cold, electricity, fire, and sonic damage; this resistance applies before its Hardness. These benefits apply only to attacks made by Gargantuan creatures or siege engines.\n\nFailure The ritual doesn't succeed.\n\nCritical Failure The target is considerably weakened, reducing its Hardness by 10 (minimum 0).","source":{"provider":"PAIZO","sourceId":"nxnGKgcVii5KTwtM","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.life-giving-form","name":"Life-Giving Form","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","light","manipulate","oracle","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transcend your physical form, becoming a beacon of healing energy. Your body exudes bright light like a torch. You gain resistance 5 to precision damage and weakness 5 to void damage, and your unarmed Strikes deal an extra 1d4 vitality damage. You can touch a living creature with an Interact action to restore (@item.level)d8[healing,vitality|shortLabel:true] Hit Points to it, and when a creature touches you with an Interact action you can allow it to gain the same healing; either way, the creature becomes temporarily immune to life-giving form's healing for 1 minute. This is a vitality healing effect. You can't heal yourself with life-giving form. A creature harmed by vitality damage (such as an undead) that touches you or damages you with an unarmed attack or non-reach melee weapon instead takes (3d4 + (@item.level - 6))[vitality] damage, and it doesn't become temporarily immune. You can Dismiss this spell.\n\nHeightened (+1) The Hit Points restored with an Interact action increases by 1d8, the vitality damage increases by 1, and the resistance and weakness increases by 1","source":{"provider":"PAIZO","sourceId":"9kOI14Jep97TzGO7","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lignify","name":"Lignify","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature made of flesh","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You turn the target's flesh slowly into wood. The target must attempt a Fortitude save. Creatures with the plant trait have a +2 circumstance bonus to saves against this spell.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Slowed 1 for 1 round.\n\nFailure The target is slowed 1 and must attempt a Fortitude save at the end of each of its turns; this ongoing save has the incapacitation trait. On a failed save, the slowed condition increases by 1 (or 2 on a critical failure). A successful save reduces the slowed condition by 1. When a creature is unable to act due to the slowed condition from lignify, the creature is permanently non-magically petrified, though it's turned to wood instead of stone. The spell ends if the creature is magically petrified or the slowed condition is removed.\n\nCritical Failure As failure, but the target is initially Slowed 2.","source":{"provider":"PAIZO","sourceId":"2hMy9ROM2dOZB8Jq","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.lure-dream","name":"Lure Dream","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","dream","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reach out to the dream realm, beckoning an animate dream to your side. This works like , except you summon an .","source":{"provider":"PAIZO","sourceId":"fRUxp4G9kG816XAt","book":"Pathfinder Lost Omens Monsters of Myth","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.manifold-lives","name":"Manifold Lives","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","emotion","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 target","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"j2redl0npv4ehyxz","formula":"6d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"j2redl0npv4ehyxz":"1d6"}},"counteraction":false,"ritual":null,"description":"You cast a creature's mind back through time, forcing them to take other paths and make other choices, experiencing countless alternate lives in an instant. The creature becomes overwhelmed with regret over paths untraveled, lives unlived, and times unrealized. The creature takes 6d6 mental damage and must attempt a Will save. After the effect is resolved, the target is then temporarily immune for 1 day.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and is Stupefied 2 for 1 round.\n\nFailure The creature takes full damage and is stupefied 2 for 1 minute. While affected, the creature must attempt another save at the start of its turn; on a failure, it's Slowed 1 for that turn as it sobs uncontrollably.\n\nCritical Failure The creature takes double damage and for 1 minute, it's Stupefied 4 and slowed 1 as it sobs uncontrollably.\nHeightened (+1) The mental damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"MT8usUfwudDVUm5H","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.mantle-of-heavens-slopes","name":"Mantle of Heaven's Slopes","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["manipulate","morph"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You surround yourself in a mantle of heavenly power, invoking the power of the layers of the celestial mountain above. Your body warps and morphs into an angelic form, made of Heaven's light. Upon Casting this Spell, pick two different options below. As a single action, which has the concentrate trait, you can lose one of the options you chose and select a different one (you don't benefit from having the same option selected twice at the same time).\n\n- Threshold's Walls Glimmering barriers form around you. You gain cover from the barriers.\n\n- Proelera's Arsenal Shimmering silver pikes surround you, imposing your might on those who would oppose you. You gain an arsenal unarmed attack, which has the reach and shove traits, in the polearm group. Your arsenal attack deals 1d10 piercing damage as its base damage, plus an additional 1d8 spirit damage, and counts as silver.\n\n- Clarion's Sanctity Your eyes glow with golden light, seeing that which others prefer remain unseen. You gain a +2 status bonus on checks to Recall Knowledge and , and when you succeed at a check to Recall Knowledge about a creature you can see, you can attempt to Sense its Motive as a free action.\n\n- Requius's Rest Your hands glow with soft white energy that spreads to your wounds. You gain fast healing 2.\n\n- Illumis's Parlance Your voice echoes like a trumpet. You can be heard clearly up to 200 feet away when you speak, if you choose to project your voice.\n\n- Iuidica's Verdict Your body pulses with scarlet light, pushing away those judged to be against you. As a free action triggered by succeeding at a Strike, you can attempt to the creature you hit","source":{"provider":"PAIZO","sourceId":"vF52ktg0wUIAlf57","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mislead","name":"Mislead","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You turn yourself and create an illusory duplicate of yourself. When you Sustain the spell, you can mentally dictate a course of action for your duplicate to follow that round. Your duplicate acts as though it had your full number of actions, though it can't actually affect anything in the environment. Both the duplicate and your invisibility persist for the spell's duration. Performing a hostile action doesn't end mislead's invisibility, just like a 4th-rank spell. A creature that determines the duplicate is an illusion doesn't necessarily know you're invisible, and one that can see your invisible form doesn't necessarily know your duplicate is an illusion.\n\nIf you Cast a Spell, attack, or otherwise interact with another creature, as a part of that action you can attempt a Deception check against observers' Perception DCs to convince them your duplicate used that action. This doesn't fool anyone who's aware your duplicate is an illusion, nor does it work if the attack obviously couldn't have come from the duplicate. For instance, if you fired a ray, you could make it look like it came from the duplicate as long as the duplicate was positioned appropriately, but if you attacked with a sword and your duplicate was across the room from the target, your Deception check would automatically fail.","source":{"provider":"PAIZO","sourceId":"WPXzPl7YbMEIGWfi","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.missed-cue","name":"Missed Cue","kind":"SPELL","rank":6,"rarity":"RARE","traits":["concentrate","emotion","fear","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"7JuaSjPOenc3HtiT","formula":"12d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"7JuaSjPOenc3HtiT":"2d6"}},"counteraction":false,"ritual":null,"description":"You make the spell's target believe they had something incredibly important to say but forgot to say it, and now they've missed their opportunity. Sensations of overwhelming panic akin to stage fright flood the target's mind, causing them to suffer excruciating mental anguish and take 12d6 mental damage. The target might even become filled with the conviction that they've doomed themselves by missing their cue. The target must attempt a Will save.\nCritical Success The conviction of a missed cue is only a fleeting notion that passes quickly without any effect on the target.\n\nSuccess The target takes half damage and is Frightened 1.\n\nFailure The target takes full damage and becomes Frightened 2. In addition, the target is Slowed 1 for as long as they remain frightened.\n\nCritical Failure The target takes double damage and becomes Frightened 3. In addition, the target is slowed 1 for as long as they remain frightened.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"oCdcZ8EqoC1K0Drq","book":"Pathfinder #205: Singer, Stalker, Skinsaw Man","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.moonlight-bridge","name":"Moonlight Bridge","kind":"SPELL","rank":6,"rarity":"UNCOMMON","traits":["concentrate","focus","light","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a bridge of radiant, shimmering moonlight.\n\nThe 10-foot-wide span must start at the ground on a point within range, and it extends as a horizontal plane, either in a straight line or at any angle up to 45 degrees upward or downward, for up to 120 feet.\n\nThis bridge has AC 10, Hardness 30, and 60 Hit Points, and it's immune to all damage (except force, spirit, and damage from Strikes with the property rune). You and your allies can cross the bridge normally, but other creatures simply pass through it if they try to do so. The bridge blocks physical, ethereal, and incorporeal attacks from crossing, whether from above or below.\n\nYou can Dismiss the spell.\nHeightened (+1) The length of the bridge increases by 20 feet, and its Hit Points increase by 20, and you can increase the width of the span by up to an additional 5 feet.","source":{"provider":"PAIZO","sourceId":"In2A7GCyxxaqZdPI","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.natures-reprisal","name":"Nature's Reprisal","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","plant","poison","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"all squares on the ground that contain plants in an 80-foot burst","area":{"shape":"BURST","feet":80}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"6","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"The plant life within the area begins to writhe and lash out against your enemies as you call upon nature to impede your foes. To your enemies, the area becomes difficult terrain, and areas that were naturally difficult terrain due to plants become greater difficult terrain as well as hazardous terrain, dealing 6 poison damage to an enemy each time it enters an affected square.\n\nHeightened (+1) The poison damage of the hazardous terrain increases by 1.","source":{"provider":"PAIZO","sourceId":"YtBZq49N4Um1cwm7","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.necrotize","name":"Necrotize","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"12d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You necrotize part of a creature's body, harming it and debilitating it as its body putrefies, mimicking the natural process of decay. The target takes 12d6 void damage and one of the following debilitations; roll [[/r 1d4]] to randomly determine which. The effects depend on its Fortitude save.\n\n- Bones The target's bones necrotize and become spongy and weak, giving it weakness 3 to bludgeoning damage.\n\n- Joints The target's joints necrotize, making its movements ungainly and clumsy. It becomes Clumsy 1.\n\n- Legs The target's legs necrotize, as well as any other limbs associated with forms of movement, making it harder for the creature to move. The target takes a –10-foot status penalty to its Speeds.\n\n- Muscles The target's muscles necrotize, rotting away. The target becomes Enfeebled 1.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and the debilitation lasts until the end of your next turn.\n\nFailure The target takes full damage and the debilitation lasts for 1 minute.\n\nCritical Failure The target takes double damage, and you can pick a second debilitation to apply, in addition to the one you rolled randomly. Both debilitations last for 1 minute.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"6lO6uMQxbqmYho0e","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.never-mind","name":"Never Mind","kind":"SPELL","rank":6,"rarity":"COMMON","traits":["concentrate","curse","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You drastically reduce the target's mental faculties. The target must attempt a Will save. The effects of this curse can be removed only through effects that target curses.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Stupefied 2 for 1 round.\n\nFailure The target is Stupefied 4 with an unlimited duration.\n\nCritical Failure The target's intellect is permanently reduced below that of an animal, and it treats its Charisma, Intelligence, and Wisdom modifiers as –5. It loses all class abilities that require mental faculties, including all spellcasting. If the target is a PC, they become an NPC under the GM's control.","source":{"provider":"PAIZO","sourceId":"5BbU1V6wGSGbrmRD","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
